const tierPrice=MK.tierPrice=(p,q)=>{ let pct=0; (p.tiers||[]).forEach(x=>{ if(q>=x.from) pct=Math.max(pct,x.pct); }); const pr=promoFor(p); let base=p.pr; if(pr&&pr.kind==='disc') base=r2(base*(1-pr.pct/100)); return {unit:r2(base*(1-pct/100)),pct,promo:pr&&pr.kind==='disc'?pr:null}; };
