const form=MK.form=(root)=>{ root=root||document; const o={}; root.querySelectorAll('input[name],select[name],textarea[name]').forEach(el=>{ if(el.type==='checkbox') o[el.name]=el.checked; else if(el.type==='radio'){ if(el.checked) o[el.name]=el.value; else if(!(el.name in o)) o[el.name]=''; } else o[el.name]=el.value.trim(); }); return o; };
const check=MK.check=(rules)=>{ UI.err={}; if(MK.xr){ rules=rules.concat(MK.xr()); MK.xr=null; } rules.forEach(([n,ok,msg])=>{ if(!UI.err[n]&&!ok) UI.err[n]=msg; }); const bad=Object.keys(UI.err); if(bad.length){ UI.focusBad=true; toast(t(`Fix ${bad.length} field${bad.length>1?'s':''} to continue`,`صحّح ${bad.length} حقل للمتابعة`)); } return !bad.length; };
