ACT.tieradd=()=>{ const d=readP(); const L=d.tiers; const last=L[L.length-1]; L.push({from:last?last.from+5:5,pct:last?last.pct+2:3}); UI.tiers=L; UI.pdraft=Object.assign(prodOrBlank(),d,{tiers:L}); rr(); const i=document.getElementById('f-tf'+(L.length-1)); i&&i.focus(); };
ACT.tierdel=i=>{ const d=readP(); d.tiers.splice(Number(i),1); UI.tiers=d.tiers; UI.pdraft=Object.assign(prodOrBlank(),d); rr(); };
const prodOrBlank=()=>{ const id=C.q.get('id'); return Object.assign({},id?prod(id):{st:'draft'}); };
ACT.psample=()=>{ const s=sampleProduct('draft'); S.seq.p--; const id=C.q.get('id'); UI.pdraft=Object.assign(prodOrBlank(),s,{id:id||undefined,st:id?prod(id).st:'draft'}); UI.tiers=s.tiers; clearErr(); rr(); };
ACT.psv=a=>{ const [id,st]=a.split(':'); const d=readP(); UI.tiers=d.tiers; if(!pvalid(d)){ UI.pdraft=Object.assign(prodOrBlank(),d); return rr(); }
 UI.pdraft=null; UI.tiers=null; let p=id?prod(id):null; if(p){ const was=p.st; Object.assign(p,d); p.st=st==='review'?'review':(was==='active'&&st==='draft'?'draft':st); p.why=''; p.ts=now(); } else { p=Object.assign({id:'pr'+(++S.seq.p),sel:'s1',ts:now()},d,{st}); S.products.push(p); }
 if(p.st==='review') notify('admin','tag',[`Listing to review: ${p.en}`,`منتج للمراجعة: ${p.ar}`],'a.listing?id='+p.id);
 save(); go(S.me.st==='approved'?'s.products':'s.setup'); toast(p.st==='review'?t('Submitted for listing review','أُرسل لمراجعة المنتج'):t('Saved as draft','حُفظ كمسودة')); };
ACT.pdel=id=>sheet(t('Delete this product?','حذف هذا المنتج؟'),`<p class="why">${t('Buyers will no longer see it. Past orders keep their details.','لن يراه المشترون. تحتفظ الطلبات السابقة بتفاصيلها.')}</p>${btns(btn(t('Delete','حذف'),{act:'pdelok',arg:id,k:'bad'}),btn(t('Cancel','إلغاء'),{act:'shclose',k:'sec'}))}`);
ACT.pdelok=id=>{ S.products=S.products.filter(p=>p.id!==id); save(); closeSheet(true); go('s.products'); toast(t('Product deleted','حُذف المنتج')); };
