const parseCSV=txt=>{ const out=[]; let row=[],cur='',q=false; for(let i=0;i<txt.length;i++){ const c=txt[i]; if(q){ if(c==='"'){ if(txt[i+1]==='"'){ cur+='"'; i++; } else q=false; } else cur+=c; } else if(c==='"') q=true; else if(c===','){ row.push(cur); cur=''; } else if(c==='\n'||c==='\r'){ if(c==='\r'&&txt[i+1]==='\n') i++; row.push(cur); out.push(row); row=[]; cur=''; } else cur+=c; } if(cur||row.length){ row.push(cur); out.push(row); } return out.filter(r=>r.some(x=>x.trim())); };
const mapTbl=P=>{ const MAP=UI.cmapx||{}; return sec(t('Match columns','مطابقة الأعمدة'),`<div class="pad"><p class="why">${t('We matched columns by name. Change any match, or choose “Don’t import”.','طابقنا الأعمدة بالاسم. غيّر أي مطابقة أو اختر «لا تستورد».')}</p></div><table class="tbl"><thead><tr><th scope="col">${t('Column in file','العمود في الملف')}</th><th scope="col">${t('MENAFoods field','حقل منافودز')}</th></tr></thead><tbody>${P.H0.map((c,i)=>{ const v=MAP[c]||(CSV_COLS.includes(c)?c:''); return `<tr><td>${LTR(c)}</td><td><label class="vh" for="cm-${i}">${t('MENAFoods field for ','حقل منافودز لـ ')}${esc(c)}</label><select class="inp sm" id="cm-${i}" data-act="cmapset" data-arg="${esc(c)}" dir="ltr"><option value="">${t('Don’t import','لا تستورد')}</option>${CSV_COLS.map(k=>`<option value="${k}"${k===v?' selected':''}>${k}</option>`).join('')}</select></td></tr>`; }).join('')}</tbody></table>`,{act:P.miss?pill('warn',t(`${P.miss.length} required not matched`,`${P.miss.length} مطلوبة غير مطابقة`)):pill('ok',t('All required matched','كل المطلوب مطابق'))}); };
ACT.cmapset=(v,el)=>{ const c=el.dataset.arg; UI.cmapx=Object.assign({},UI.cmapx||{}); UI.cmapx[c]=v||'__skip'; if(v&&v!==c) UI.cmapx[v]=UI.cmapx[v]||'__skip'; if(v===c) delete UI.cmapx[c]; rr(); const n=[...document.querySelectorAll('[data-act=cmapset]')].find(x=>x.dataset.arg===c); n&&n.focus(); };
const gOf={rice:'sack',oil:'tin',dairy:'milk',frozen:'frozen',canned:'can',spice:'jar',pack:'box'};
const csvRows=txt=>{ const R=parseCSV(txt); if(!R.length) return {err:t('The file is empty','الملف فارغ')}; const H0=R[0].map(h=>h.trim().toLowerCase()); const MAP=UI.cmapx||{}; const H=H0.map(h=>MAP[h]||h); const miss=CSV_COLS.filter(c=>!['tier1_from','tier1_pct','pack_ar'].includes(c)&&!H.includes(c)); if(miss.length) return {err:t('Missing columns: ','أعمدة ناقصة: ')+miss.join(', ')+t(' — match them below',' — طابقها أدناه'),H,H0,miss};
 const today=new Date(now()).toISOString().slice(0,10);
 const rows=R.slice(1).map((r,i)=>{ const o={}; H.forEach((h,j)=>o[h]=(r[j]||'').trim()); const e=[]; if(!o.title_en) e.push(t('title missing','العنوان ناقص')); if(!CATS.some(c=>c[0]===o.category)) e.push(t('unknown category','فئة غير معروفة')); if(!(Number(o.price_excl_vat)>0)) e.push(t('price must be above 0','السعر يجب أن يكون أكبر من 0')); if(!STORE.some(s=>s[0]===o.storage)) e.push(t('storage must be ambient, chilled or frozen','التخزين: ambient أو chilled أو frozen')); if(!(o.best_before>today)) e.push(t('best_before missing or past','best_before ناقص أو منتهٍ'));
  const ar=!o.title_ar||!o.pack_ar; return {n:i+2,o,e,ar}; }); return {H,H0,rows}; };
