 if(o.st==='packed') return sec(t('Ship or hand over','الشحن أو التسليم'),`<div class="pad">${radio('smode',[['pickup',t('MENAFoods courier picks up','مندوب منافودز يستلم'),t('Choose a collection time at your location','اختر وقت الاستلام من موقعك')],['self',t('I deliver with my own fleet or courier','أوصل بأسطولي أو شركة شحن')]],UI.smode||'pickup',t('How will it ship?','كيف سيُشحن؟'),{cards:true,act:'smode'})}</div>${(UI.smode||'pickup')==='pickup'?slotPicker():selfShip()}`);
