const RET=MK.RET=[['missing',['Missing part of the order','نقص في الطلب'],['Fewer cases than ordered','كراتين أقل من المطلوب']],['damaged',['Damaged on arrival','تالف عند الوصول'],['Crushed, leaking or opened','مضغوط أو مسرّب أو مفتوح']],['expiry',['Expired or too close to expiry','منتهي أو قريب الانتهاء'],['Less shelf life than listed','صلاحية أقل من المعلن']],['temp',['Cold chain problem','مشكلة في سلسلة التبريد'],['Chilled or frozen goods arrived warm','وصلت المبردات أو المجمدات دافئة']],['wrong',['Wrong item','صنف خاطئ'],['Not what I ordered','ليس ما طلبته']]];
const retReason=MK.retReason=k=>tt((RET.find(r=>r[0]===k)||[0,[k,k]])[1]);
const retSt=MK.retSt=r=>({partial:t('Partial refund approved','تمت الموافقة على استرداد جزئي'),replaced:t('Replacement sent','أُرسل بديل'),resolved_p:t('Resolved · partial refund','حُسم · استرداد جزئي'),resolved_r:t('Resolved · replacement','حُسم · استبدال'),open:t('Waiting for seller','بانتظار البائع'),accepted:t('Refund approved','تمت الموافقة على الاسترداد'),declined:t('Declined by seller','رفضه البائع'),dispute:t('With MENAFoods (dispute)','لدى منافودز (نزاع)'),resolved_b:t('Resolved · buyer refunded','حُسم · استرد المشتري'),resolved_s:t('Resolved · in seller’s favour','حُسم · لصالح البائع')})[r.st]||r.st;
const retTone=r=>({partial:'ok',replaced:'ok',resolved_p:'ok',resolved_r:'ok',open:'warn',accepted:'ok',declined:'bad',dispute:'warn',resolved_b:'ok',resolved_s:'mut'})[r.st];
const retAmt=MK.retAmt=o=>{ const r=o.ret; if(r.amt!=null&&['partial','resolved_p'].includes(r.st)) return r.amt; return r2(r.items.reduce((a,x)=>{ const i=o.items.find(y=>y.pid===x.pid); return a+(i?i.unit*x.q:0); },0)); };
def('s.returns',{t:()=>t('Returns & disputes','المرتجعات والنزاعات'),back:'s.more',tab:'s.more',render:()=>{ const L=myO().filter(o=>o.ret); return L.length?sec('',rows(L.map(o=>({ic:'ret',tone:retTone(o.ret),t:`${t('Order','طلب')} ${LTR('#'+o.id)} · ${esc(retReason(o.ret.reason))}`,s:`${esc(tt([o.buyer.en,o.buyer.ar]))} · ${M(retAmt(o))} · ${ago(o.ret.ts)}`,pill:[retTone(o.ret),retSt(o.ret)],go:'s.return?id='+o.id})))):empty('ret',t('No returns','لا مرتجعات'),t('If a buyer reports a problem with a delivered order, it appears here.','إذا أبلغ مشترٍ عن مشكلة في طلب مُسلّم يظهر هنا.')); }});
MK.REF['s.return']=MK.REF['s.returns'];
def('s.return',{t:q=>t('Return · order ','إرجاع · الطلب ')+'#'+q.get('id'),back:'s.returns',tab:'s.more',render:q=>{ const o=ordFor(q.get('id')); if(!o||!o.ret) return empty('ret',t('Return not found','طلب الإرجاع غير موجود'),'',btn(t('Back','رجوع'),{go:'s.returns'})); const r=o.ret;
 let h=`<div class="pad"><div class="stat-row"><span>${dt(r.ts)}</span>${pill(retTone(r),retSt(r))}</div></div>`;
 h+=sec(t('What the buyer reported','ما أبلغ عنه المشتري'),kv([[t('Reason','السبب'),esc(retReason(r.reason))],[t('Items','الأصناف'),r.items.map(x=>{ const i=o.items.find(y=>y.pid===x.pid); return `${N(x.q)} × ${esc(tt([i.en,i.ar]))}`; }).join('<br>')],[t('Refund requested','الاسترداد المطلوب'),M(retAmt(o))],r.note?[t('Buyer note','ملاحظة المشتري'),esc(r.note)]:null,[t('Photos','الصور'),r.photo?`<span class="ph-ph">${I('camera',18)} ${t('1 photo (simulated)','صورة واحدة (محاكاة)')}</span>`:t('None','لا يوجد')],[t('Respond by','الرد قبل'),r.st==='open'?MK.retDue(o):'—']]));
 h+=MK.retTimeline(o); if(r.st==='open') h+=MK.retDecision(o);
 if(r.sellerNote) h+=sec(t('Your response','ردك'),`<p class="pad">${esc(tx(r.sellerNote))}</p>`);
 if(r.adminNote) h+=sec(t('MENAFoods decision','قرار منافودز'),`<p class="pad">${esc(tx(r.adminNote))}</p>`);
 h+=sec('',rows([{ic:'chat',tone:'brand',t:t('Message the buyer','راسل المشتري'),act:'msgbuyer',arg:o.id},{ic:'box',tone:'brand',t:t('View order','عرض الطلب'),go:'s.order?id='+o.id}]));
 return h; }});
ACT.retok=id=>{ const o=ordFor(id); o.ret.st='accepted'; o.ret.dec=now(); o.ret.sellerNote=['Refund approved','تمت الموافقة على الاسترداد']; notify('buyer','ret',[`Refund approved for order #${o.id}`,`تمت الموافقة على استرداد الطلب ‎#${o.id}`],'b.order?id='+o.id); save(); rr(); toast(t('Refund approved · deducted from next payout','تمت الموافقة · يُخصم من الدفعة القادمة')); };
ACT.retno=id=>sheet(t('Decline this return?','رفض طلب الإرجاع؟'),`${fld('retwhy',t('Explain why (the buyer and MENAFoods will see this)','وضّح السبب (يراه المشتري ومنافودز)'),{ta:true,req:true,max:300})}<p class="why">${t('The buyer can ask MENAFoods to review (dispute).','يمكن للمشتري طلب مراجعة منافودز (نزاع).')}</p>${btns(btn(t('Decline return','ارفض الإرجاع'),{act:'retnook',arg:id,k:'bad'}),btn(t('Cancel','إلغاء'),{act:'shclose',k:'sec'}))}`);
ACT.retnook=id=>{ const sh=document.querySelector('.sh-wrap'); const f=form(sh); const i=sh.querySelector('#f-retwhy'); if(f.retwhy.length<5){ i.setAttribute('aria-invalid','true'); if(!sh.querySelector('#retwhy-e')) i.insertAdjacentHTML('afterend',`<p class="err" id="retwhy-e" role="alert">${t('Write at least a short reason','اكتب سببًا موجزًا على الأقل')}</p>`); i.setAttribute('aria-describedby','retwhy-e'); i.focus(); return; }
 const o=ordFor(id); o.ret.st='declined'; o.ret.dec=now(); o.ret.sellerNote=f.retwhy; notify('buyer','ret',[`Return declined for order #${o.id} — you can ask MENAFoods to review`,`رُفض إرجاع الطلب ‎#${o.id} — يمكنك طلب مراجعة منافودز`],'b.order?id='+o.id); save(); closeSheet(true); rr(); toast(t('Return declined · buyer notified','رُفض الإرجاع · أُبلغ المشتري')); };
