MK.REF['s.payouts']=['Shopify · Finance — Payout balance + View payouts; Shopify · Payouts empty state “Keep track of your payouts” (Learn more / View transactions)','4d049521-0dbf-4de6-b1bb-ee508426a6e7','screens',['c64a7249-ff6e-42a5-b8ce-3f7a98304421']];
const pend=MK.pend=sel=>{ const O=S.orders.filter(o=>o.sel===sel&&o.st==='delivered'&&!o.paid); const R=S.orders.filter(o=>o.sel===sel&&o.ret&&['accepted','partial','resolved_b','resolved_p'].includes(o.ret.st)&&!o.ret.ded); const P=S.promos.filter(x=>x.sel===sel&&x.kind==='spon');
 const T=O.map(ordTot); const sum=k=>r2(T.reduce((a,x)=>a+x[k],0)); const refunds=R.map(o=>{ const a=retAmt(o); const rate=commRate(o.items[0].cat)/100; return {ord:o.id,amt:r2(a*1.15-a*rate*1.15)}; }); const ref=r2(refunds.reduce((a,x)=>a+x.amt,0)); const ads=r2(P.reduce((a,x)=>a+Math.max(0,promoSpend(x)-(x.billed||0)),0));
 return {O,R,P,sub:sum('sub'),vat:sum('vat'),comm:sum('comm'),cvat:sum('cvat'),refunds,ref,ads,net:r2(sum('net')-ref-ads)}; };
const runPayout=MK.runPayout=sel=>{ const p=pend(sel); if(!p.O.length&&!p.refunds.length&&!p.ads) return null; const id=String(++S.seq.po); const last=sel==='s1'?(S.me.bank.iban||'').slice(-4):'0000';
 const po={id,sel,ts:now(),orders:p.O.map(o=>o.id),sub:p.sub,vat:p.vat,comm:p.comm,cvat:p.cvat,refunds:p.refunds,ads:p.ads,net:p.net,st:p.net>=0?'paid':'carry',iban:last};
 p.O.forEach(o=>{ o.paid=id; o.tl.paid=now(); }); p.R.forEach(o=>o.ret.ded=id); p.P.forEach(x=>x.billed=promoSpend(x)); S.payouts.unshift(po);
 notify(sel==='s1'?'seller':'admin','wallet',[`Payout #${id} sent: SAR ${fmt(po.net)}`,`أُرسلت الدفعة ‎#${id}: ${fmt(po.net)} ريال`],'s.payout?id='+id); return po; };
def('s.payouts',{t:()=>t('Payouts','المدفوعات'),back:'s.more',tab:'s.more',render:()=>{ const p=pend('s1'); const L=S.payouts.filter(x=>x.sel==='s1'); const k=S.me.bank;
 let h=sec('',`<div class="pad"><p class="lbl">${t('Payout balance','رصيد المدفوعات')} ${sample()}</p><p class="bigm">${M(p.net)}</p><p class="why">${t(`${p.O.length} delivered order(s) waiting for the next weekly payout (sample schedule)`,`${p.O.length} طلب مُسلّم بانتظار الدفعة الأسبوعية التالية (جدول تجريبي)`)}</p></div>`+row({ic:'bank',tone:'brand',t:t('Bank account','الحساب البنكي'),s:k.ok?MK.ibanM(k.iban.slice(-4)):t('Not added','غير مضاف'),go:'s.bank'}));
 h+=L.length?sec(t('Payouts','المدفوعات'),rows(L.map(x=>({ic:'wallet',tone:x.st==='paid'?'ok':'warn',t:`${t('Payout','دفعة')} ${LTR('#'+x.id)} · ${M(x.net)}`,s:`${dt(x.ts)} · ${t(`${x.orders.length} orders`,`${x.orders.length} طلبات`)}`,pill:x.st==='paid'?['ok',t('Paid','مدفوعة')]:['warn',t('Carried forward','مُرحّلة')],go:'s.payout?id='+x.id})))):`<div class="pad">${empty('wallet',t('Keep track of your payouts','تابع مدفوعاتك'),t('This is where you’ll see a list of all your payouts and the details of each transaction.','هنا ترى قائمة مدفوعاتك وتفاصيل كل عملية.'),btns(btn(t('View transactions','عرض العمليات'),{act:'gotrans',k:'sec'})))}</div>`;
 return h; }});
MK.REF['s.payout']=['alias · payout breakdown (selling price, commission, seller fee, available to cash out); Grailed · Earnings (sold price, commission, processing fee, total earnings)','97f87d71-214e-4d9e-8772-5391e21493b2','screens',['7d077a25-34be-4075-84a7-5f40ccf69967']];
const statement=MK.statement=x=>kv([[t('Sales (excl. VAT)','المبيعات (قبل الضريبة)'),M(x.sub)],[t('VAT collected 15%','الضريبة المحصّلة 15%'),M(x.vat)],[t('MENAFoods commission','عمولة منافودز'),M(-x.comm)],[t('VAT on commission 15%','ضريبة العمولة 15%'),M(-x.cvat)],x.refunds.length?[t('Refunds (net of reversed commission)','المبالغ المستردة (بعد عكس العمولة)'),M(-x.refunds.reduce((a,r)=>a+r.amt,0))]:null,x.ads?[t('Sponsored products','المنتجات الممولة'),M(-x.ads)]:null,[t('Net payout','صافي الدفعة'),M(x.net),'tot']]);
def('s.payout',{t:q=>t('Payout ','الدفعة ')+'#'+q.get('id'),back:'s.payouts',tab:'s.more',render:q=>{ const x=S.payouts.find(p=>p.id===q.get('id')); if(!x) return empty('wallet',t('Payout not found','الدفعة غير موجودة'),'',btn(t('Payouts','المدفوعات'),{go:'s.payouts'}));
 return `<div class="pad center"><p class="bigm">${M(x.net)}</p><p class="why">${t('Sent','أُرسلت')} ${dt(x.ts)} · ${MK.ibanM(x.iban)}</p>${pill('ok',t('Paid','مدفوعة'))}</div>`+sec(t('Statement','كشف الحساب'),statement(x),{act:sample()})+sec(t('Orders in this payout','الطلبات في هذه الدفعة'),rows(x.orders.map(id=>{ const o=ordFor(id); return o?{ic:'box',tone:'mut',t:`${LTR('#'+id)} · ${esc(tt([o.buyer.en,o.buyer.ar]))}`,s:M(ordTot(o).net),go:'s.order?id='+id}:null; })))+`<div class="pad">${btn(t('Download statement (CSV)','نزّل الكشف (CSV)'),{act:'stmtcsv',arg:x.id,k:'sec',ic:'dl'})}${note(t('MENAFoods issues a monthly tax invoice for its commission plus 15% VAT. It’s linked below.','تصدر منافودز فاتورة ضريبية شهرية للعمولة مع ضريبة 15%. تجدها أدناه.'))}</div>`; }});
ACT.stmtcsv=id=>{ const x=S.payouts.find(p=>p.id===id); const L=[['payout','order','sales_excl_vat','vat','commission','vat_on_commission','net']].concat(x.orders.map(oid=>{ const T=ordTot(ordFor(oid)); return [x.id,oid,T.sub,T.vat,-T.comm,-T.cvat,T.net]; })).concat(x.refunds.map(r=>[x.id,r.ord+' refund','','','','',-r.amt])).concat(x.ads?[[x.id,'sponsored products','','','','',-x.ads]]:[]).concat([[x.id,'TOTAL','','','','',x.net]]);
 const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob(['\ufeff'+L.map(r=>r.join(',')).join('\n')],{type:'text/csv'})); a.download=`menafoods-payout-${x.id}-sample.csv`; document.body.appendChild(a); a.click(); setTimeout(()=>{ URL.revokeObjectURL(a.href); a.remove(); },500); toast(t('Statement downloaded','تم تنزيل الكشف')); };

