MK.REF['s.inbox']=['Etsy · conversation — header with shop + “Typically responds within 24 hours”, product card in message, “We scan and review messages” notice, composer; Nextdoor · item card pinned above the chat; Fiverr · order card in conversation','2c63e20a-2503-4588-b49e-9777ea43106a','screens',['7b9c0a64-e26d-4080-91a6-9bbcda72487f','fb5e8da1-57f5-4aef-b920-a1ae58f8a266']];
const thread=MK.thread=(sel,ordId)=>{ let m=S.msgs.find(x=>x.sel===sel&&x.ord===ordId); if(!m){ m={id:'m'+(++S.seq.m),sel,ord:ordId,items:[],unS:0,unB:0,ts:now()}; S.msgs.unshift(m); } return m; };
