const inboxList=(who)=>{ const L=S.msgs.filter(m=>who==='s'?m.sel==='s1':true).filter(m=>m.items.length||who==='s'); if(!L.length) return empty('chat',t('No messages yet','لا رسائل بعد'),who==='s'?t('Buyers can message you about an order. You can also message a buyer from any order.','يمكن للمشترين مراسلتك بشأن طلب، ويمكنك مراسلة المشتري من أي طلب.'):t('Message a seller from any order.','راسل البائع من أي طلب.'));
 return sec('',rows(L.map(m=>{ const o=ordFor(m.ord); const last=m.items[m.items.length-1]; const un=who==='s'?m.unS:m.unB; return {ic:'chat',tone:un?'brand':'mut',t:(who==='s'?esc(o?tt([o.buyer.en,o.buyer.ar]):''):esc(sellerName(m.sel)))+` · ${LTR('#'+m.ord)}`,s:last?esc(last.tx):t('No messages yet','لا رسائل بعد'),pill:un?['info',t(`${un} new`,`${un} جديد`)]:null,go:(who==='s'?'s':'b')+'.thread?id='+m.id}; }))); };
def('s.inbox',{t:()=>t('Inbox','الرسائل'),tab:'s.inbox',render:()=>inboxList('s')});
const chatView=(m,me)=>{ const o=ordFor(m.ord); const other=me==='s'?(o?tt([o.buyer.en,o.buyer.ar]):''):sellerName(m.sel);
 return {b:`${o?`<div class="pin">${G(o.items[0].g,'sm')}<div class="rb"><b>${t('Order','طلب')} ${LTR('#'+o.id)}</b><small>${itemsLine(o)} · ${M(ordTot(o).tot)}</small></div>${pill(...ostPill(o))}</div>`:''}<p class="why center">${me==='b'?t('Typically responds within a few hours (sample)','يرد عادة خلال ساعات (تجريبي)'):esc(other)}</p><ol class="chat" aria-label="${t('Messages','الرسائل')}" aria-live="polite">${m.items.map(x=>`<li class="${x.by===me?'me':''}"><span class="vh">${x.by===me?t('You','أنت'):esc(x.by==='sys'?'MENAFoods':other)}: </span>${esc(x.tx)}<small>${dt(x.ts,{hour:'2-digit',minute:'2-digit'})}</small></li>`).join('')||`<li class="sys">${t('Start the conversation','ابدأ المحادثة')}</li>`}</ol><p class="fine">${I('shield',14)} ${t('MENAFoods may review messages for fraud prevention and to resolve disputes. Don’t share bank details here.','قد تراجع منافودز الرسائل لمنع الاحتيال وحل النزاعات. لا تشارك بيانات بنكية هنا.')}</p>`,
 dock:`<label class="vh" for="f-chat">${t('Write a message','اكتب رسالة')}</label><input class="inp grow" id="f-chat" name="chat" maxlength="500" autocomplete="off" placeholder="${t('Write a message','اكتب رسالة')}" data-enter="1">${btn('<span class="vh">'+t('Send','إرسال')+'</span>',{act:'send',arg:me+':'+m.id,ic:'send',lbl:t('Send message','أرسل الرسالة')})}`}; };
def('s.thread',{t:q=>{ const m=S.msgs.find(x=>x.id===q.get('id')); const o=m&&ordFor(m.ord); return o?tt([o.buyer.en,o.buyer.ar]):t('Conversation','محادثة'); },back:'s.inbox',tab:'s.inbox',render:q=>{ const m=S.msgs.find(x=>x.id===q.get('id')); if(!m) return empty('chat',t('Conversation not found','المحادثة غير موجودة'),''); if(m.unS){ m.unS=0; save(); } return chatView(m,'s'); }});
ACT.send=a=>{ const [me,id]=a.split(':'); const i=document.getElementById('f-chat'); const v=(i.value||'').trim(); if(!v){ i.focus(); toast(t('Write a message first','اكتب رسالة أولًا')); return; } const m=S.msgs.find(x=>x.id===id); m.items.push({by:me,tx:v,ts:now()}); m.ts=now(); if(me==='s'){ m.unB++; notify('buyer','chat',[`New message from ${sellerName(m.sel)}`,`رسالة جديدة من ${sellerName(m.sel)}`],'b.thread?id='+m.id); } else { m.unS++; notify('seller','chat',['New message from a buyer','رسالة جديدة من مشترٍ'],'s.thread?id='+m.id); } save(); rr(); const n=document.getElementById('f-chat'); n&&n.focus(); };
document.addEventListener('keydown',e=>{ if(e.key==='Enter'&&e.target.id==='f-chat'){ e.preventDefault(); const b=document.querySelector('[data-act=send]'); b&&b.click(); } });

