ACT.csync=()=>{ const c=C_(); c.last=now(); elog('stock','in',myP().length,'ok',['Stock levels updated','تم تحديث المخزون'],true); save(); rr(); toast(t('Sync complete (simulated)','اكتملت المزامنة (محاكاة)')); };
ACT.cpause=()=>{ const c=C_(); c.st=c.st==='paused'?'live':'paused'; audit('seller',c.st==='paused'?'Sync paused':'Sync resumed',sysN(c.sys)); save(); rr(); toast(c.st==='paused'?t('Sync paused','أُوقفت المزامنة'):t('Sync resumed','استؤنفت المزامنة')); };
ACT.cexpire=()=>{ const c=C_(); c.st='expired'; elog('stock','in',0,'err',['Sign-in expired (401). Reconnect to resume.','انتهى الدخول (401). أعد الربط للاستئناف.']); audit('system','Token expired',sysN(c.sys)); notify('seller','alert',['Your ERP connection expired — reconnect','انتهى اتصال نظامك — أعد الربط'],'s.conn'); save(); rr(); };
ACT.cdisc=()=>sheet(t('Disconnect?','قطع الاتصال؟'),`<p class="why">${t('Sync stops right away. Your products and published prices stay in MENAFoods. Your keys and sign-in tokens are deleted from the connector.','تتوقف المزامنة فورًا. تبقى منتجاتك وأسعارك المنشورة في منافودز. وتُحذف مفاتيحك ورموز الدخول من الموصّل.')}</p>${btns(btn(t('Disconnect','قطع الاتصال'),{act:'cdiscok',k:'bad'}),btn(t('Cancel','إلغاء'),{act:'shclose',k:'sec'}))}`);
ACT.cdiscok=()=>{ const c=C_(); audit('seller','Disconnected — tokens deleted',sysN(c.sys)); E().conn=null; closeSheet(true); save(); go('s.conn'); toast(t('Disconnected','تم قطع الاتصال')); };

