 if(['odoo','server'].includes(m)||(m==='file'&&UI.fmode==='gs')||sftp) R.push(['url',/^(https?:\/\/|sftp\.)?[a-z0-9.-]+\.[a-z]{2,}(:\d+)?(\/\S*)?$/i.test(f.url||''),t('Enter a valid address','أدخل عنوانًا صحيحًا')]);
