 if(['key','odoo','server'].includes(m)||sftp) R.push(['k1',(f.k1||'').length>=8,t('Enter the full key (8+ characters)','أدخل المفتاح كاملًا (8 أحرف أو أكثر)')]);
 if(!check(R)) return rr(); clearErr();
 const finish=()=>{ closeSheet(true); const c=C_();
  if(qh('re')&&c&&c.sys===id){ c.st='live'; c.last=now(); elog('stock','in',myP().length,'ok',['Reconnected — caught up','أُعيد الربط — تمت المزامنة']); audit('seller','Reconnected',s[1]); save(); go('s.conn'); toast(t('Reconnected','أُعيد الربط')); return; }
  const acct=m==='oauth'||m==='key'?f.acct:m==='file'?t('File / sheet','ملف / جدول'):m==='custom'?(sftp?f.url:'Webhook'):f.db;
  E().conn={sys:id,acct,ts:now(),st:'map',maps:{},rules:Object.fromEntries(RULES.map(r=>[r[0],r[2]])),freq:'15',margin:true};
  const as=qh('assist'); if(as){ const a=E().assist.find(x=>x.id===as); if(a){ a.st='keys'; a.tl.keys=now(); } }
  audit('seller','Connected — keys encrypted, not visible to staff',s[1]); UI.secret=null; save(); go('s.cmap'); toast(t('Connected — now check the field mapping','تم الربط — راجع مطابقة الحقول الآن')); };
 if(m==='oauth'){ ACT.cauthok=finish; sheet(t(`Sign in to ${s[1]}`,`سجّل الدخول إلى ${s[2]}`),`<div class="ctr">${logo(id,'lg')}</div><p class="why">${t(`This is ${s[1]}’s own sign-in page (simulated). MENAFoods never sees your password.`,`هذه صفحة الدخول الخاصة بـ ${s[2]} (محاكاة). لا ترى منافودز كلمة مرورك.`)}</p>${kv([[t('Organisation','المنشأة'),esc(f.acct)],[t('Access requested','الصلاحيات المطلوبة'),t('Items, stock, price lists (read) · Sales orders, invoices, bills (write)','الأصناف والمخزون وقوائم الأسعار (قراءة) · أوامر البيع والفواتير والمشتريات (كتابة)')]])}${btns(btn(t('Allow access','اسمح بالوصول'),{act:'cauthok'}),btn(t('Cancel','إلغاء'),{act:'shclose',k:'sec'}))}`); return; }
