ACT.golive=()=>{ const c=C_(); const L=previewSet(); const e=E();
 L.filter(x=>x.k==='upd').forEach(x=>{ const p=prod(x.pid); if(p) p.qty=Number(x.to); });
 L.filter(x=>x.k==='price').forEach(x=>e.prices.unshift({id:eid('pc'),pid:x.pid,sel:'s1',name:x.name,from:x.from,to:x.to,ts:now(),st:'pending'}));
 L.filter(x=>x.k==='new').forEach(x=>S.products.push(Object.assign(sampleProduct('draft'),{en:x.name[0],ar:x.name[1],g:x.g,pr:0,cost:0,tiers:[],qty:0,src:'erp'})));
 L.filter(x=>x.k==='issue').forEach(x=>e.conflicts.unshift({id:eid('cf'),name:x.name,what:x.what,ts:now(),st:'open',kind:x.kind}));
 c.st='live'; c.last=now(); UI.onlyIss=false;
 for(let i=20;i>0;i-=3) e.log.push({id:eid('L'),ts:now()-i*HOUR,type:'stock',dir:'in',n:myP().length,st:i===11?'err':'ok',fixed:i===11,msg:i===11?['Rate limit reached (429) — retried automatically','تجاوز الحد (429) — أُعيدت المحاولة تلقائيًا']:['Scheduled stock sync','مزامنة المخزون المجدولة'],undo:false});
 elog('catalog','in',2,'ok',['2 new products saved as drafts','حُفظ منتجان جديدان كمسودات'],true); elog('stock','in',myP().length,'ok',['First stock sync','أول مزامنة للمخزون'],true);
 elog('invoices','out',1,'err',['Invoice for order #7088 rejected: buyer VAT number missing in your ERP customer','رُفضت فاتورة الطلب ‎#7088: الرقم الضريبي للمشتري ناقص في نظامك']);
 audit('seller','Went live',sysOf(c.sys)[1]); notify('seller','tag',['Price changes from your ERP are waiting for you','تغييرات أسعار من نظامك بانتظارك'],'s.cprice'); save(); go('s.conn'); toast(t('You’re live — sync is running','تم التشغيل — المزامنة تعمل')); };

