ACT.srejok=id=>{ const sh=document.querySelector('.sh-wrap'); const f=form(sh); if(!f.srr){ const e=sh.querySelector('#srr-e'); e.hidden=false; e.setAttribute('role','alert'); sh.querySelector('input[name=srr]').focus(); return; } const s=S.sellers.find(x=>x.id===id); s.st='rejected'; s.why=SREJ.find(r=>r[0]===f.srr)[1].map(x=>x+(f.srn?' — '+f.srn:'')); s.dec=now();
 if(s.me){ S.me.st='rejected'; S.me.why=s.why; notify('seller','alert',[`Changes needed: ${s.why[0]}`,`مطلوب تعديلات: ${s.why[1]}`],'s.setup'); } save(); closeSheet(true); rr(); toast(t('Sent to seller','أُرسل للبائع')); };

MK.REF['a.listings']=['Aboard · Approvals table; Calendly · tabs with counts + search (listing moderation queue)','9ce069a2-2cbe-4c94-a7f5-b57050e50ca0','screens',['3cd7e903-497a-4087-aa32-e4efd0ba2810']];
def('a.listings',{wide:true,t:()=>t('Listing moderation','مراجعة المنتجات'),tab:'a.listings',render:()=>{ const v=tabOf('al','review'); const A=S.products.filter(p=>p.st!=='draft'); const L=A.filter(p=>p.st===v);
 let h=tabs('al',[['review',t('In review','قيد المراجعة'),A.filter(p=>p.st==='review').length],['active',t('Active','نشط'),A.filter(p=>p.st==='active').length],['rejected',t('Changes needed','يحتاج تعديل'),A.filter(p=>p.st==='rejected').length]],v,t('Listing status','حالة المنتج'));
 if(!L.length) return h+empty('tag',t('Queue is clear','القائمة فارغة'),v==='review'?t('Listings sellers submit for review appear here.','تظهر هنا المنتجات التي يرسلها البائعون للمراجعة.'):'');
 return h+adminTable([t('Product','المنتج'),t('Seller','البائع'),t('Category','الفئة'),t('Price / case','السعر / كرتون'),t('Storage','التخزين'),t('Flags','تنبيهات'),t('Submitted','الإرسال')],L.map(p=>{ const fl=lflags(p); return `<tr><td><button type="button" class="lnk" data-go="a.listing?id=${p.id}">${esc(pn(p))}</button></td><td>${esc(sellerName(p.sel))}</td><td>${catName(p.cat)}</td><td>${M(p.pr)}</td><td>${tt(STORE.find(s=>s[0]===p.storage)[1]).split(' · ')[0]}</td><td>${fl.length?pill('warn',fl.length):pill('ok','0')}</td><td>${ago(p.ts)}</td></tr>`; }),t('Listings','المنتجات')); }});
const lflags=MK.lflags=p=>{ const f=[]; if(['dairy','frozen'].includes(p.cat)&&p.storage==='ambient') f.push(t('Dairy/frozen listed as ambient storage','ألبان/مجمدات مسجلة بتخزين عادي')); if(p.cat==='frozen'&&p.storage!=='frozen') f.push(t('Frozen category but not frozen storage','فئة مجمدات بتخزين غير مجمد')); if(p.exp&&daysTo(p.exp)<30) f.push(t('Best-before is less than 30 days away','الانتهاء خلال أقل من 30 يومًا')); if(!p.ar||p.ar===p.en) f.push(t('Arabic title missing','العنوان العربي ناقص')); if((p.tiers||[]).some(x=>x.pct>30)) f.push(t('Tier discount above 30%','خصم شريحة أعلى من 30%')); return f; };
MK.REF['a.listing']=['Shopify · Add product (filled) as the read-only preview; Aboard · Approvals (approve / reject)','041b50f4-738c-443d-b2dd-28cd15a7b335','screens',['9ce069a2-2cbe-4c94-a7f5-b57050e50ca0']];
def('a.listing',{wide:true,t:()=>t('Review listing','مراجعة المنتج'),back:'a.listings',tab:'a.listings',render:q=>{ const p=prod(q.get('id')); if(!p) return empty('tag',t('Listing not found','المنتج غير موجود'),'',btn(t('Back','رجوع'),{go:'a.listings'})); const fl=lflags(p);
 let h=`<div class="pad"><div class="stat-row"><span>${esc(sellerName(p.sel))} · ${ago(p.ts)}${p.bulk?' · '+t('CSV import','استيراد CSV'):''}</span>${pill(...pstPill(p))}</div></div><div class="cols"><div>`;
 h+=sec(t('As buyers will see it','كما يراه المشترون'),`<div class="pad">${G(p.g,'lg')}<h3>${esc(p.en)}</h3><p dir="rtl" lang="ar">${esc(p.ar)}</p><p class="why">${esc(tt(p.pack))} · ${catName(p.cat)}</p><p>${M(p.pr)} <small>${t('excl. VAT / case','قبل الضريبة / كرتون')}</small></p></div>`+kv([[t('Minimum order','الحد الأدنى'),N(p.moq)+' '+t('cases','كرتون')],[t('Tiers','الشرائح'),(p.tiers||[]).map(x=>`${x.from}+ → −${x.pct}%`).join('<br>')||'—'],[t('Storage','التخزين'),tt(STORE.find(s=>s[0]===p.storage)[1])],[t('Shelf life','الصلاحية'),p.shelf?p.shelf+' '+t('days','يوم'):'—'],[t('Best before','الانتهاء'),LTR(p.exp||'—')],[t('Stock','المخزون'),N(p.qty)+' '+t('cases','كرتون')],[t('Commission','العمولة'),LTR(commRate(p.cat)+'%')]]))+`</div><div>`;
 h+=sec(t('Checks','الفحوص'),fl.length?rows(fl.map(f=>({ic:'alert',tone:'warn',t:f}))):rows([{ic:'check',tone:'ok',t:t('No automatic flags','لا تنبيهات تلقائية')}]),{foot:t('Sample rule set: required food-safety fields, SFDA number, price outliers.','قواعد تجريبية: حقول سلامة الغذاء الإلزامية، رقم الهيئة، الأسعار الشاذة.')});
 if(p.st==='review') h+=sec(t('Decision','القرار'),`<div class="pad">${btns(btn(t('Approve listing','اعتمد المنتج'),{act:'lapprove',arg:p.id}),btn(t('Request changes','اطلب تعديلات'),{act:'lreject',arg:p.id,k:'bad'}))}</div>`);
 if(p.why) h+=sec(t('Reason sent','السبب المرسل'),`<p class="pad">${esc(tx(p.why))}</p>`);
 return h+`</div></div>`; }});
ACT.lapprove=id=>{ const p=prod(id); p.st='active'; p.why=''; p.appr=now(); notify(p.sel==='s1'?'seller':'admin','check',[`Listing approved: ${p.en} is live`,`اعتُمد المنتج: ${p.ar} ظاهر الآن`],'s.prod?id='+id); save(); const nx=S.products.find(x=>x.st==='review'); if(nx){ go('a.listing',{id:nx.id}); } else go('a.listings'); toast(t('Approved · now in the buyer catalogue','اعتُمد · ظاهر في كتالوج المشترين')); };
ACT.lreject=id=>sheet(t('Request changes','طلب تعديلات'),`${fld('lrn',t('What should the seller fix?','ما الذي يجب تعديله؟'),{ta:true,req:true,max:300,val:lflags(prod(id)).join('. ')})}${btns(btn(t('Send to seller','أرسل للبائع'),{act:'lrejok',arg:id,k:'bad'}),btn(t('Cancel','إلغاء'),{act:'shclose',k:'sec'}))}`);
ACT.lrejok=id=>{ const sh=document.querySelector('.sh-wrap'); const v=form(sh).lrn; if(v.length<5){ const i=sh.querySelector('#f-lrn'); i.setAttribute('aria-invalid','true'); i.focus(); toast(t('Explain what to fix','وضّح المطلوب')); return; } const p=prod(id); p.st='rejected'; p.why=v; notify(p.sel==='s1'?'seller':'admin','alert',[`Changes needed: ${p.en}`,`مطلوب تعديل: ${p.ar}`],'s.prod?id='+id); save(); closeSheet(true); go('a.listings'); toast(t('Sent back to seller','أُعيد للبائع')); };

MK.REF['a.commission']=['Cleo AI · fee table card (re-used read-only by sellers); Zoho CRM · Price Book rows (editable rate rows). No Mobbin admin commission-settings screen found — open decision','9fbdabff-5afc-4aa3-8461-94bb4b10fe2a','screens',['0da88eb8-6ebe-4c7a-837c-6c7c8f7d7a9f']];
def('a.commission',{wide:true,t:()=>t('Commission settings','إعدادات العمولة'),tab:'a.commission',render:()=>{ const c=S.comm;
 return {b:`<div class="pad">${alert_('warn',t('Sample rates','نسب تجريبية'),t('These are placeholders for the preview. MENAFoods finance and legal must set the real rates and notice period.','هذه قيم مؤقتة للعرض. تحدد مالية وقانونية منافودز النسب الفعلية وفترة الإشعار.'))}</div>`+sec(t('Rate per category (% of item price excl. VAT)','النسبة لكل فئة (% من السعر قبل الضريبة)'),`<div class="pad">${CATS.map(([k])=>`<div class="crow">${fld('c_'+k,catName(k),{req:true,val:c[k],type:'number',min:0,step:'0.5',mode:'decimal',ltr:true,suf:'%'})}</div>`).join('')}${fld('c_def',t('Default for new categories','الافتراضي للفئات الجديدة'),{req:true,val:c.def,type:'number',min:0,step:'0.5',mode:'decimal',ltr:true,suf:'%'})}</div>`,{act:pill('info',LTR('v'+c.ver))})
 +(c.log.length?sec(t('Change log','سجل التغييرات'),rows(c.log.slice(0,5).map(l=>({ic:'clock',tone:'mut',t:`v${l.ver} · ${esc(l.txt)}`,s:dt(l.ts)})))):''),
 dock:`<p class="fine">${t('Saving creates a new version. Applies to orders placed after saving; sellers are notified.','الحفظ ينشئ إصدارًا جديدًا. يطبّق على الطلبات بعد الحفظ؛ ويُبلغ البائعون.')}</p>${btn(t('Save new rates','احفظ النسب الجديدة'),{act:'csave'})}`}; }});
ACT.csave=()=>{ const f=form(document.getElementById('main')); const keys=CATS.map(c=>c[0]).concat(['def']); const vals={}; keys.forEach(k=>vals[k]=Number(f['c_'+k]));
 if(!check(keys.map(k=>['c_'+k,vals[k]>=0&&vals[k]<=30&&f['c_'+k]!=='',t('Use 0–30%','استخدم 0–30%')]))) return rr();
 const ch=keys.filter(k=>vals[k]!==S.comm[k]); if(!ch.length){ toast(t('No changes','لا تغييرات')); return; } const c=S.comm; c.ver++; c.log.unshift({ver:c.ver,ts:now(),txt:ch.map(k=>`${k==='def'?'default':k} ${c[k]}→${vals[k]}%`).join(', ')}); Object.assign(c,vals); c.ts=now();
 notify('seller','pct',[`Commission schedule updated to v${c.ver}`,`حُدّث جدول العمولة إلى الإصدار ${c.ver}`],'s.agree'); save(); rr(); toast(t(`Saved as v${c.ver}`,`حُفظ كإصدار ${c.ver}`)); };

MK.REF['a.disputes']=['Aboard · Approvals table for the queue; dispute decision has no direct Mobbin reference — open decision','9ce069a2-2cbe-4c94-a7f5-b57050e50ca0','screens'];
def('a.disputes',{wide:true,t:()=>t('Disputes','النزاعات'),tab:'a.disputes',render:()=>{ const L=S.orders.filter(o=>o.ret&&['dispute','resolved_b','resolved_s'].includes(o.ret.st)); if(!L.length) return empty('scale',t('No disputes','لا نزاعات'),t('If a seller declines a return and the buyer asks MENAFoods to review, it appears here.','إذا رفض البائع إرجاعًا وطلب المشتري مراجعة منافودز يظهر هنا.'));
 return adminTable([t('Order','الطلب'),t('Buyer','المشتري'),t('Seller','البائع'),t('Reason','السبب'),t('Amount','المبلغ'),t('Status','الحالة')],L.map(o=>`<tr><td><button type="button" class="lnk" data-go="a.dispute?id=${o.id}">${LTR('#'+o.id)}</button></td><td>${esc(tt([o.buyer.en,o.buyer.ar]))}</td><td>${esc(sellerName(o.sel))}</td><td>${esc(retReason(o.ret.reason))}</td><td>${M(retAmt(o))}</td><td>${pill(retTone(o.ret),retSt(o.ret))}</td></tr>`),t('Disputes','النزاعات')); }});
MK.REF['a.dispute']=MK.REF['a.disputes'];
def('a.dispute',{wide:true,t:q=>t('Dispute · order ','نزاع · الطلب ')+'#'+q.get('id'),back:'a.disputes',tab:'a.disputes',render:q=>{ const o=ordFor(q.get('id')); if(!o||!o.ret) return empty('scale',t('Not found','غير موجود'),''); const r=o.ret;
 return `<div class="cols"><div>`+sec(t('Buyer says','يقول المشتري'),kv([[t('Reason','السبب'),esc(retReason(r.reason))],[t('Note','الملاحظة'),esc(r.note||'—')],[t('Photo','صورة'),r.photo?t('1 (simulated)','1 (محاكاة)'):t('None','لا يوجد')],[t('Amount','المبلغ'),M(retAmt(o))],[t('Escalation note','ملاحظة التصعيد'),esc(r.esc||'—')]]))+sec(t('Seller says','يقول البائع'),`<p class="pad">${esc(tx(r.sellerNote)||'—')}</p>`)+`</div><div>`+sec(t('Order','الطلب'),kv([[t('Delivered','التسليم'),o.tl&&o.tl.delivered?dt(o.tl.delivered):'—'],[t('Shipping','الشحن'),esc((o.ship||{}).carrier||'—')],[t('Total','الإجمالي'),M(ordTot(o).tot)]]))
 +MK.retTimeline(o)+(r.st==='dispute'?MK.disDecision(o):sec(t('Decision','القرار'),`<p class="pad">${esc(tx(r.adminNote))}</p>`))+`</div></div>`; }});
ACT.dres=a=>{ const [id,w]=a.split(':'); const f=form(document.getElementById('main')); if(!check([['dnote',f.dnote.length>=5,t('Write a short decision note','اكتب ملاحظة قرار موجزة')]])) return rr(); const o=ordFor(id); o.ret.st=w==='b'?'resolved_b':'resolved_s'; o.ret.adminNote=f.dnote; o.ret.res=now();
 notify('seller','scale',[`Dispute on #${o.id} resolved`,`حُسم النزاع على ‎#${o.id}`],'s.return?id='+o.id); notify('buyer','scale',[`Dispute on #${o.id} resolved`,`حُسم النزاع على ‎#${o.id}`],'b.order?id='+o.id); save(); rr(); toast(t('Decision sent to both sides','أُرسل القرار للطرفين')); };

MK.REF['a.payouts']=['Shopify · Finance payout balance pattern, applied per seller; statement = alias / Grailed breakdown','4d049521-0dbf-4de6-b1bb-ee508426a6e7','screens',['97f87d71-214e-4d9e-8772-5391e21493b2']];
def('a.payouts',{wide:true,t:()=>t('Seller payouts','مدفوعات البائعين'),tab:'a.payouts',render:()=>{ const sel=S.sellers.filter(s=>s.st==='approved');
 return `<div class="pad">${note(t('Demo control: “Run payout now” ignores the 7-day hold so you can see the statement straight away.','أداة عرض: «حوّل الآن» يتجاوز مهلة 7 أيام لترى الكشف مباشرة.'))}</div>`+adminTable([t('Seller','البائع'),t('Delivered, unpaid','مُسلّم غير محوّل'),t('Balance','الرصيد'),t('Action','إجراء')],sel.map(s=>{ const p=pend(s.id); return `<tr><td>${esc(lang==='ar'?s.ar:s.en)}</td><td>${N(p.O.length)}</td><td>${M(p.net)}</td><td>${btn(t('Run payout now','حوّل الآن'),{act:'runpo',arg:s.id,sm:true,dis:!p.O.length&&!p.ads&&!p.refunds.length,lbl:t('Run payout now','حوّل الآن')+' · '+(s.en)})}</td></tr>`; }),t('Payout balances','أرصدة المدفوعات'))
 +(S.payouts.length?sec(t('Recent payouts','آخر المدفوعات'),rows(S.payouts.slice(0,8).map(x=>({ic:'wallet',tone:'ok',t:`${LTR('#'+x.id)} · ${esc(sellerName(x.sel))} · ${M(x.net)}`,s:dt(x.ts)})))):''); }});
ACT.runpo=id=>{ const po=runPayout(id); save(); rr(); toast(po?t(`Payout #${po.id} sent (simulated)`,`أُرسلت الدفعة ‎#${po.id} (محاكاة)`):t('Nothing to pay','لا شيء للتحويل')); };
/* ================= ERP Connector · MENAFoods admin (connection health only — never seller ERP data, costs or bills) ================= */
const CNAV=[['a.conns',['Connections','الاتصالات']],['a.cassist',['Assisted setup','الإعداد بمساعدة']],['a.cguard',['Price checks','مراجعة الأسعار']],['a.ccat',['Connector catalogue','كتالوج الموصلات']],['a.caudit',['Audit log','سجل التدقيق']]];
const cnav=cur=>`<nav class="subnav" aria-label="${t('Connector admin','إدارة الموصلات')}">${CNAV.map(([r,l])=>`<a href="#/${r}"${r===cur?' aria-current="page"':''}>${tt(l)}</a>`).join('')}</nav>`;
const adminPriv=()=>`<div class="pad">${note(t('Privacy: admins see connection health and published prices only. Seller ERP data, costs, purchase bills and keys are never shown here.','الخصوصية: يرى المشرفون صحة الاتصال والأسعار المنشورة فقط. لا تظهر هنا بيانات أنظمة البائعين أو تكاليفهم أو فواتير الشراء أو المفاتيح.'))}</div>`;
const allConns=()=>{ const e=E(); const L=e.others.slice(); if(e.conn) L.unshift({sel:'s1',sys:e.conn.sys,st:e.conn.st,last:e.conn.last||0,ok:e.log.filter(l=>l.st!=='err').length,err:e.log.filter(l=>l.st==='err'&&!l.fixed).length}); return L; };
const CST={live:['ok',['Live','يعمل']],paused:['warn',['Paused','متوقف']],expired:['bad',['Expired','منتهي']],setup:['info',['In setup','قيد الإعداد']],map:['info',['In setup','قيد الإعداد']],rules:['info',['In setup','قيد الإعداد']],preview:['info',['In setup','قيد الإعداد']]};
MK.REF['a.conns']=['Aboard · Approvals table (status pill per row); Gumloop · Activity — success/error per connector; Sentry · Integration dashboard request log','9ce069a2-2cbe-4c94-a7f5-b57050e50ca0','screens',['56b76a1c-1083-4220-a4a1-2c340e80fe23','de9d35ab-8456-4255-8fa7-49000ea9b7a2']];
def('a.conns',{wide:true,t:()=>t('Seller connections','اتصالات البائعين'),tab:'a.conns',render:()=>{ const L=allConns(); const v=tabOf('acn','all'); const F=L.filter(c=>v==='all'||(v==='att'?['expired','paused'].includes(c.st)||c.err>0:c.st==='live'));
 return cnav('a.conns')+adminPriv()+tabs('acn',[['all',t('All','الكل'),L.length],['live',t('Live','يعمل'),L.filter(c=>c.st==='live').length],['att',t('Needs attention','يحتاج انتباه'),L.filter(c=>['expired','paused'].includes(c.st)||c.err>0).length]],v,t('Filter connections','تصفية الاتصالات'))
 +sec('',adminTable([t('Seller','البائع'),t('System','النظام'),t('Status','الحالة'),t('Last sync','آخر مزامنة'),t('Open errors','أخطاء مفتوحة'),t('Action','إجراء')],F.map(c=>{ const s=CST[c.st]||CST.setup; return `<tr><td>${esc(sellerName(c.sel))}</td><td>${esc(sysN(c.sys))}</td><td>${pill(s[0],tt(s[1]))}</td><td>${c.last?ago(c.last):'—'}</td><td>${N(c.err||0)}</td><td>${c.st==='expired'?btn(t('Remind seller','ذكّر البائع'),{act:'anudge',arg:c.sel,k:'sec',sm:true,lbl:t('Remind seller to reconnect: ','ذكّر البائع بإعادة الربط: ')+sellerName(c.sel)}):'—'}</td></tr>`; }),t('Seller connections','اتصالات البائعين')),{raw:true}); }});
ACT.anudge=sel=>{ notify('seller','alert',['MENAFoods: please reconnect your ERP','منافودز: يرجى إعادة ربط نظامك'],'s.conn'); audit('admin','Reminder to reconnect sent',sellerName(sel)); save(); toast(t('Reminder sent','أُرسل التذكير')); };
MK.REF['a.cassist']=['Aboard · Approvals table with status + approver; Thrive Market · status tracker. Secure credential link (no viewing of keys) — open decision','9ce069a2-2cbe-4c94-a7f5-b57050e50ca0','screens',['1212eea7-7c05-4ed4-a465-8f8b232b2c69']];
def('a.cassist',{wide:true,t:()=>t('Assisted setup queue','قائمة الإعداد بمساعدة'),tab:'a.conns',render:()=>{ const A=E().assist;
 const act=a=>!a.who&&['requested','booked'].includes(a.st)?btn(t('Assign to me','عيّنه لي'),{act:'aasg',arg:a.id,sm:true,lbl:t('Assign to me: ','عيّنه لي: ')+a.desk}):!a.link&&['assigned','booked'].includes(a.st)?btn(t('Send secure key link','أرسل رابط المفاتيح الآمن'),{act:'alink',arg:a.id,sm:true,k:'sec',lbl:t('Send secure key link: ','أرسل رابط المفاتيح الآمن: ')+a.desk}):a.st==='keys'?btn(t('Mark connected','علّم كمتصل'),{act:'acon',arg:a.id,sm:true,lbl:t('Mark connected: ','علّم كمتصل: ')+a.desk}):pill(a.link&&a.st!=='verified'?'info':'ok',a.link&&['assigned','booked'].includes(a.st)?t('Waiting for seller','بانتظار البائع'):tt((AST.find(x=>x[0]===a.st)||AST[0])[1]));
 return cnav('a.cassist')+`<div class="pad">${note(t('Never ask sellers for passwords or keys. Send the secure link — the seller types keys themselves and they are encrypted for the connector only.','لا تطلب من البائعين كلمات مرور أو مفاتيح. أرسل الرابط الآمن — يكتب البائع المفاتيح بنفسه وتُشفّر للموصّل فقط.'))}</div>`
 +(A.length?sec('',adminTable([t('Ticket','التذكرة'),t('Seller','البائع'),t('System','النظام'),t('Channel','القناة'),t('Topic','الموضوع'),t('Session','الجلسة'),t('Status / action','الحالة / الإجراء')],A.map(a=>`<tr><td>${LTR(a.desk)}</td><td>${esc(sellerName(a.sel||'s1'))}</td><td>${esc(sysN(a.sys))}</td><td>${tt(CHN[a.ch]||CHN.chat)}</td><td>${esc(a.topic||'—')}</td><td>${esc(a.slot||'—')}</td><td>${act(a)}</td></tr>`),t('Assisted setup requests','طلبات الإعداد بمساعدة')),{raw:true}):empty('help',t('No requests','لا طلبات'),t('Seller requests for setup help appear here.','تظهر هنا طلبات البائعين للمساعدة.'))); }});
