const live=()=>S.products.filter(p=>p.st==='active'&&S.sellers.some(s=>s.id===p.sel&&s.st==='approved'));
const pcard=p=>{ const tp=tierPrice(p,p.moq); return `<a class="pcard" href="${href('b.product',{id:p.id})}">${G(p.g)}${sponsored(p)?`<span class="spons">${'<bdi>Sponsored · إعلان</bdi>'}</span>`:''}<span class="pc-b"><b>${esc(pn(p))}</b><small>${t('by','من')} ${esc(sellerName(p.sel))}</small><span class="pc-p">${M(tp.unit)}${tp.promo?` <s class="mut">${M(p.pr)}</s>`:''}</span><small>${esc(tt(p.pack))} · ${t('Min.','الحد الأدنى')} ${N(p.moq)}</small>${p.qty<=0?pill('bad',t('Out of stock','نفد')):''}</span></a>`; };
def('b.shop',{t:()=>t('Marketplace','السوق'),tab:'b.shop',render:()=>{ const cat=tabOf('bcat','all'); let L=live().filter(p=>cat==='all'||p.cat===cat); L.sort((a,b)=>(sponsored(b)-sponsored(a))||(b.ts-a.ts));
 let h=`<div class="pad"><p class="why">${t('Products from verified MENAFoods marketplace sellers. Prices exclude 15% VAT.','منتجات من بائعين موثّقين في سوق منافودز. الأسعار قبل ضريبة 15%.')} ${sample()}</p></div>`;
 h+=tabs('bcat',[['all',t('All','الكل')]].concat(CATS.filter(c=>live().some(p=>p.cat===c[0])).map(([k])=>[k,catName(k).split(/[,،&]/)[0].trim()])),cat,t('Category','الفئة'));
 return h+(L.length?`<div class="pgrid">${L.map(pcard).join('')}</div>`:empty('store',t('No marketplace products yet','لا منتجات في السوق بعد'),t('Seller products appear here once MENAFoods approves the seller and the listing.','تظهر منتجات البائع هنا بعد اعتماد البائع والمنتج من منافودز.'),btn(t('Switch to seller','بدّل إلى البائع'),{act:'role',arg:'seller',k:'sec'}))); }});
MK.REF['b.product']=['Etsy · “Meet your seller” card (rating, response time, Message seller); TikTok Shop · About this shop (Message / View shop, shop performance); eBay · detailed seller ratings; Faire · case pack + minimum','54bb8c83-e3f8-48ab-86ea-693332e1e7eb','screens',['91d6ed1a-043a-4954-9a45-99b3c9d8ca99','0a1d1fbe-fc99-4653-b9ac-091f9d3ac580','0acaaf2f-5562-4d8e-a3a4-1cf2607cd9ba']];
const sellerCard=sid=>{ const R=S.reviews.filter(r=>r.sel===sid); const s=S.sellers.find(x=>x.id===sid)||{}; const avg=R.length?R.reduce((a,r)=>a+r.stars,0)/R.length:s.rating||0; const n=R.length||s.nrev||0;
 return sec(t('Meet your seller','تعرّف على البائع'),`<div class="pad center"><span class="logo lg" aria-hidden="true">${esc(sellerName(sid).slice(0,1))}</span><h3>${esc(sellerName(sid))}</h3><p class="why">${n?`${avg.toFixed(1)} ★ · ${t(`${n} reviews`,`${n} مراجعة`)}`:t('New seller','بائع جديد')} · ${esc(tt(CITIES.find(c=>c[0]===s.city)||[s.city||'',s.city||'']))}</p><p class="why">${I('shield',16)} ${t('Verified by MENAFoods (CR, VAT, SFDA)','موثّق من منافودز (السجل، الضريبة، الهيئة)')}</p>${btns(btn(t('View shop','عرض المتجر'),{go:'b.store?id='+sid,k:'sec',sm:true}))}</div>`); };
def('b.product',{t:q=>{ const p=prod(q.get('id')); return p?pn(p):t('Product','المنتج'); },back:'b.shop',tab:'b.shop',render:q=>{ const p=prod(q.get('id')); if(!p||p.st!=='active') return empty('tag',t('This product isn’t available','هذا المنتج غير متاح'),'',btn(t('Back to marketplace','عودة للسوق'),{go:'b.shop'}));
 const q0=UI.bq&&UI.bq.id===p.id?UI.bq.n:p.moq; const tp=tierPrice(p,q0);
 let h=`<div class="pad">${G(p.g,'lg')}${sponsored(p)?`<span class="spons">${'<bdi>Sponsored · إعلان</bdi>'}</span>`:''}<h2 class="ph2">${esc(pn(p))}</h2><p class="why">${esc(tt(p.pack))} · ${t('Sold by','يبيعه')} ${esc(sellerName(p.sel))}</p><p class="bigm">${M(tp.unit)} <small>${t('excl. VAT / case','قبل الضريبة / كرتون')}</small></p>${tp.promo?pill('ok',t(`${tp.promo.pct}% off · seller discount`,`خصم ${tp.promo.pct}% من البائع`)):''}</div>`;
 h+=sec(t('Wholesale pricing','أسعار الجملة'),kv([[t(`${p.moq}+ cases (minimum)`,`${p.moq}+ كرتون (الحد الأدنى)`),M(tierPrice(p,p.moq).unit)]].concat((p.tiers||[]).map(x=>[t(`${x.from}+ cases`,`${x.from}+ كرتون`),M(tierPrice(p,x.from).unit)+' '+pill('ok','−'+x.pct+'%')]))));
 h+=sec(t('Details','التفاصيل'),kv([[t('Storage','التخزين'),tt(STORE.find(s=>s[0]===p.storage)[1])],[t('Best before (current stock)','الانتهاء (المخزون الحالي)'),LTR(p.exp||'—')],[t('Shelf life','الصلاحية'),p.shelf?p.shelf+' '+t('days','يوم'):'—'],[t('In stock','المتوفر'),p.qty>0?N(p.qty)+' '+t('cases','كرتون'):t('Out of stock','نفد')]])+(p.about?`<p class="pad">${esc(p.about)}</p>`:''));
 h+=sellerCard(p.sel);
 return {b:h,dock:p.qty>0?`<div class="stp" role="group" aria-label="${t('Quantity in cases','الكمية بالكرتون')}"><button type="button" class="ib" data-act="bq" data-arg="${p.id}:-1" aria-label="${t('Fewer','أقل')}"${q0<=p.moq?' disabled':''}>−</button><output aria-live="polite">${q0}</output><button type="button" class="ib" data-act="bq" data-arg="${p.id}:1" aria-label="${t('More','أكثر')}"${q0>=p.qty?' disabled':''}>+</button></div>${btn(t('Add to cart','أضف للسلة')+' · '+M(tp.unit*q0),{act:'badd',arg:p.id})}`:btn(t('Out of stock','نفد المخزون'),{dis:true,full:true})}; }});
ACT.bq=a=>{ const [id,d]=a.split(':'); const p=prod(id); const cur=UI.bq&&UI.bq.id===id?UI.bq.n:p.moq; UI.bq={id,n:Math.min(p.qty,Math.max(p.moq,cur+Number(d)))}; rr(); const b=document.querySelector(`[data-act=bq][data-arg="${a}"]:not([disabled])`)||document.querySelector('[data-act=badd]'); b&&b.focus(); };
ACT.badd=id=>{ const p=prod(id); const n=UI.bq&&UI.bq.id===id?UI.bq.n:p.moq; S.cart[id]=(S.cart[id]||0)+n; UI.bq=null; save(); rr(); toast(t(`Added ${n} × ${pn(p)}`,`أُضيف ${n} × ${pn(p)}`)); };
def('b.store',{t:q=>sellerName(q.get('id')||'s1'),back:'b.shop',tab:'b.shop',render:q=>{ const id=q.get('id')||'s1'; const L=live().filter(p=>p.sel===id); return sellerCard(id)+(L.length?`<div class="pgrid">${L.map(pcard).join('')}</div>`:empty('store',t('No products live yet','لا منتجات ظاهرة بعد'),id==='s1'?t('Your listings appear here after MENAFoods approves them.','تظهر منتجاتك هنا بعد اعتمادها من منافودز.'):'')); }});

