MK.REF['b.cart']=['Reuses the MENAFoods buyer cart/checkout (Fresh Market working preview); seller grouping per Faire Wholesale orders by brand','67f53dca-d3c2-42db-9290-c441f5403813','screens'];
const cartLines=()=>Object.keys(S.cart).map(id=>({p:prod(id),q:S.cart[id]})).filter(x=>x.p);
const WINS=[['Tomorrow · 7–9 AM','غدًا · 7–9 ص'],['Tomorrow · 9–11 AM','غدًا · 9–11 ص'],['In 2 days · 2–4 PM','بعد يومين · 2–4 م']];
def('b.cart',{t:()=>t('Cart','السلة'),tab:'b.cart',render:()=>{ const L=cartLines(); if(!L.length) return empty('cart',t('Your cart is empty','سلتك فارغة'),t('Add products from marketplace sellers.','أضف منتجات من بائعي السوق.'),btn(t('Browse marketplace','تصفّح السوق'),{go:'b.shop'}));
 const by={}; L.forEach(x=>(by[x.p.sel]=by[x.p.sel]||[]).push(x)); let sub=0, h='';
 Object.keys(by).forEach(sid=>{ h+=sec(t('From ','من ')+esc(sellerName(sid)),by[sid].map(({p,q})=>{ const tp=tierPrice(p,q); sub+=tp.unit*q; const bad=q<p.moq?t(`Minimum ${p.moq} cases`,`الحد الأدنى ${p.moq} كرتون`):q>p.qty?t(`Only ${p.qty} in stock`,`المتوفر ${p.qty} فقط`):''; return `<div class="row">${G(p.g,'sm')}<span class="rb"><span class="rt">${esc(pn(p))}</span><span class="rs">${M(tp.unit)} × ${q}${tp.pct?' '+pill('ok','−'+tp.pct+'%'):''}</span>${bad?`<span class="rs err-t">${bad}</span>`:''}</span><span class="stp sm" role="group" aria-label="${t('Quantity for ','الكمية لـ ')}${esc(pn(p))}"><button type="button" class="ib" data-act="cq" data-arg="${p.id}:-1" aria-label="${t('Fewer','أقل')}">−</button><output>${q}</output><button type="button" class="ib" data-act="cq" data-arg="${p.id}:1" aria-label="${t('More','أكثر')}">+</button></span></div>`; }).join('')); });
 const vat=r2(sub*VAT); const can=L.every(({p,q})=>q>=p.moq&&q<=p.qty);
 h+=sec(t('Delivery','التوصيل'),`<div class="pad">${row({ic:'pin',tone:'brand',t:esc(tt([S.buyer.en,S.buyer.ar]))+' '+sample(),s:t('King Fahd Rd, Riyadh (sample address)','طريق الملك فهد، الرياض (عنوان تجريبي)')})}${radio('bwin',WINS.map((w,i)=>[i,tt(w)]),UI.bwin||0,t('Delivery window','موعد التوصيل'),{showLeg:true})}</div>`);
 h+=sec(t('Payment','الدفع'),`<div class="pad">${radio('bpay',[['credit',t('Pay on credit · Net 30','الدفع بالآجل · 30 يومًا'),t('Simulated — nothing is charged','محاكاة — لا يتم خصم شيء')],['card',t('Card, mada or Apple Pay','بطاقة أو مدى أو Apple Pay'),t('Simulated — nothing is charged','محاكاة — لا يتم خصم شيء')]],UI.bpay||'credit',t('Payment method','طريقة الدفع'),{showLeg:true})}</div>`);
 h+=sec(t('Summary','الملخص'),kv([[t('Subtotal (excl. VAT)','المجموع (قبل الضريبة)'),M(sub)],[t('VAT 15%','ضريبة 15%'),M(vat)],[t('Total','الإجمالي'),M(sub+vat),'tot']]),{foot:Object.keys(by).length>1?t('Each seller ships separately — you’ll get one order per seller.','يشحن كل بائع على حدة — ستحصل على طلب لكل بائع.'):''});
 return {b:h,dock:`<div class="dt"><small>${t('Total incl. VAT','الإجمالي شامل الضريبة')}</small>${M(sub+vat)}</div>${btn(t('Place order','تأكيد الطلب'),{act:'bplace',dis:!can})}`}; }});
ACT.cq=a=>{ const [id,d]=a.split(':'); const n=(S.cart[id]||0)+Number(d); if(n<=0) delete S.cart[id]; else S.cart[id]=n; save(); rr(); const b=document.querySelector(`[data-act=cq][data-arg="${a}"]`); b&&b.focus(); };
const mkOrder=MK.mkOrder=(sel,lines,o)=>{ const id=String(++S.seq.o); const ord={id,sel,ts:now(),st:'new',buyer:{en:S.buyer.en,ar:S.buyer.ar},addr:['King Fahd Rd, Riyadh (sample)','طريق الملك فهد، الرياض (تجريبي)'],win:o.win,pay:o.pay,src:o.src||'mini',appOrd:o.appOrd||null,items:lines.map(({p,q})=>{ const tp=tierPrice(p,q); return {pid:p.id,en:p.en,ar:p.ar,g:p.g,cat:p.cat,pack:p.pack,q,unit:tp.unit,tier:tp.pct}; }),tl:{new:now()}};
 S.orders.unshift(ord); notify(sel==='s1'?'seller':'admin','box',[`New order #${id} from ${S.buyer.en} — accept within 2 business hours`,`طلب جديد ‎#${id} من ${S.buyer.ar} — اقبله خلال ساعتي عمل`],'s.order?id='+id); return ord; };
ACT.bplace=()=>{ const f=form(document.getElementById('main')); const L=cartLines(); if(!L.every(({p,q})=>q>=p.moq&&q<=p.qty)) return; const by={}; L.forEach(x=>(by[x.p.sel]=by[x.p.sel]||[]).push(x)); const win=WINS[Number(f.bwin)||0];
 const made=Object.keys(by).map(sid=>mkOrder(sid,by[sid],{win,pay:f.bpay||'credit'})); S.cart={}; save(); go('b.order',{id:made[0].id}); setTimeout(()=>toast(t(`Order${made.length>1?'s':''} placed · sent to ${made.length} seller${made.length>1?'s':''}`,`تم الطلب · أُرسل إلى ${made.length} بائع`)),60); };

