def('b.orders',{t:()=>t('Orders','الطلبات'),tab:'b.orders',render:()=>{ const L=S.orders.filter(o=>o.src!=='app'||true); return L.length?sec('',rows(L.map(o=>({ic:'box',tone:'brand',t:`${t('Order','طلب')} ${LTR('#'+o.id)} · ${M(ordTot(o).tot)}`,s:`${esc(sellerName(o.sel))} · ${dt(o.ts)}${o.src==='app'?' · '+t('from MENAFoods app','من تطبيق منافودز'):''}`,pill:bPill(o),go:'b.order?id='+o.id})))):empty('box',t('No orders yet','لا طلبات بعد'),'',btn(t('Browse marketplace','تصفّح السوق'),{go:'b.shop'})); }});
def('b.order',{t:q=>t('Order ','الطلب ')+'#'+q.get('id'),back:'b.orders',tab:'b.orders',render:q=>{ const o=ordFor(q.get('id')); if(!o) return empty('box',t('Order not found','الطلب غير موجود'),'',btn(t('Orders','الطلبات'),{go:'b.orders'})); const T=ordTot(o); const i=bStage(o);
 let h=`<div class="pad"><div class="stat-row"><span>${dt(o.ts)}</span>${pill(...bPill(o))}</div></div>`;
 if(o.st==='rejected') h+=`<div class="pad">${alert_('bad',t('The seller couldn’t take this order','لم يتمكن البائع من قبول الطلب'),esc(tx(o.why))+' · '+t('Nothing was charged (simulated).','لم يُخصم شيء (محاكاة).'),{role:'alert'})}</div>`;
 else h+=sec(o.st==='delivered'?t('Delivered','تم التسليم'):o.st==='new'?t('Waiting for the seller to accept','بانتظار قبول البائع'):t('Shipment','الشحنة'),`<div class="pad"><div class="trk" role="list">${BST.map(([k,l],j)=>`<span role="listitem" class="${j<=i?'on':''}"${j===i?' aria-current="step"':''}>${tt(l)}</span>`).join('')}</div>${progress(i+1,4,t('Order progress','تقدّم الطلب'))}${o.ship&&o.ship.carrier&&o.st!=='delivered'?`<p class="why">${t('Shipped with','شُحن مع')} ${esc(o.ship.carrier)}${o.ship.trk?' · '+t('Tracking #','رقم التتبع')+' '+LTR(o.ship.trk):''}${o.ship.slotTxt?' · '+t('Pickup','الاستلام')+' '+esc(o.ship.slotTxt):''}</p>`:''}<p class="why">${t('Delivery window','موعد التوصيل')}: ${esc(tt(o.win))}</p>${o.st==='shipped'?btn(t('I received this order','استلمت الطلب'),{act:'brecv',arg:o.id,full:true}):''}</div>`);
 if(o.ret) h+=`<div class="pad">${alert_(retTone(o.ret),t('Return','الإرجاع')+' · '+retSt(o.ret),esc(tx(o.ret.sellerNote))+(o.ret.adminNote?' · '+t('MENAFoods','منافودز')+': '+esc(tx(o.ret.adminNote)):''),{act:o.ret.st==='declined'?btn(t('Ask MENAFoods to review','اطلب مراجعة منافودز'),{act:'besc',arg:o.id,sm:true,k:'sec'}):''})}</div>`;
 h+=sec(t('Items','الأصناف'),o.items.map(x=>row({img:x.g,t:esc(tt([x.en,x.ar])),s:`${x.q} × ${M(x.unit)}`,end:`<b>${M(x.q*x.unit)}</b>`})).join('')+kv([[t('Subtotal (excl. VAT)','المجموع (قبل الضريبة)'),M(T.sub)],[t('VAT 15%','ضريبة 15%'),M(T.vat)],[t('Total','الإجمالي'),M(T.tot),'tot']]));
 h+=sec(t('Sold by','يبيعه'),row({ic:'store',tone:'brand',t:esc(sellerName(o.sel)),s:MK.verLbl(o.sel),end:btn(t('Message','مراسلة'),{act:'bmsg',arg:o.id,k:'sec',sm:true})}));
 const acts=[]; const win=MK.retWin(o); const within=o.tl&&o.tl.delivered&&now()-o.tl.delivered<win;
 if(o.st==='delivered'&&!o.ret&&within) acts.push({ic:'ret',tone:'brand',t:t('Report a problem / request refund','أبلغ عن مشكلة / اطلب استردادًا'),s:win<DAY*2?t('Within 24 hours of delivery for chilled or frozen items (sample rule)','خلال 24 ساعة من التسليم للمبردات والمجمدات (قاعدة تجريبية)'):t('Within 3 days of delivery for ambient items (sample rule)','خلال 3 أيام من التسليم للمواد الجافة (قاعدة تجريبية)'),go:'b.return?id='+o.id});
 if(o.st==='delivered'&&!S.reviews.some(r=>r.ord===o.id)) acts.push({ic:'star',tone:'brand',t:t('Rate the seller','قيّم البائع'),go:'b.rate?id='+o.id});
 if(acts.length) h+=sec('',rows(acts));
 return h; }});
