ACT.rsend=id=>{ const d=rkeep(); const o=ordFor(id); const items=o.items.map(x=>({pid:x.pid,q:Number(d['rq_'+x.pid])||0})).filter(x=>x.q>0); const over=o.items.some(x=>(Number(d['rq_'+x.pid])||0)>x.q);
 if(!check([['rreason',!!d.reason,t('Choose a reason','اختر سببًا')],['rqty',items.length>0&&!over,over?t('You can’t return more than you received','لا يمكن إرجاع أكثر مما استلمت'):t('Enter how many cases have the problem','أدخل عدد الكراتين المتأثرة')]])) return rr();
 o.ret={reason:d.reason,note:d.note,photo:!!d.photo,items,ts:now(),st:'open'}; UI.ret=null; notify('seller','ret',[`Return requested on order #${o.id}`,`طلب إرجاع على الطلب ‎#${o.id}`],'s.return?id='+o.id); save(); go('b.order',{id}); toast(t('Request sent to the seller','أُرسل الطلب للبائع')); };
