/* ================= Review fixes (15 Nov 2026): compliance, trust, security, food safety, invoices, returns ================= */
const wrap=(id,fn)=>{ const s=MK.SCR[id]; if(!s) return; const r=s.render; s.render=q=>{ let o=r(q); if(typeof o==='string') o={b:o}; return fn(o,q)||o; }; };
const wrapA=(k,fn)=>{ const o=ACT[k]; ACT[k]=(...a)=>fn(o,...a); };
const before=(html,marker,ins)=>{ const i=html.indexOf(marker); if(i<0) return html+ins; const s=html.lastIndexOf('<section',i); return html.slice(0,s<0?i:s)+ins+html.slice(s<0?i:s); };
const dOnly=ts=>dt(ts,{day:'numeric',month:'short',year:'numeric'});
const PERISH=['chilled','frozen'];

/* ---- registry look-ups (simulated Wathq / ZATCA / SFDA / SPL) ---- */
const REG=[['cr',['Commercial Registration','السجل التجاري'],'Wathq'],['vat',['VAT registration','التسجيل الضريبي'],'ZATCA'],['sfda',['SFDA establishment licence','ترخيص منشأة الهيئة'],'SFDA'],['addr',['National address','العنوان الوطني'],'SPL']];
const lookups=MK.lookups=(b)=>{ const ts=now(); return {cr:{st:/^7\d{9}$/.test(b.cr||'')?'ok':'fail',ts},vat:{st:/^3\d{13}3$/.test(b.vat||'')?'ok':'fail',ts},sfda:{st:!b.sfda?'fail':/manual/i.test(b.sfda)?'unavail':'ok',ts},addr:{st:/^[A-Z]{4}\d{4}$/.test((b.addr||{}).short||'')?'ok':'fail',ts}}; };
const regOk=reg=>!!reg&&REG.every(([k])=>reg[k]&&['ok','manual'].includes(reg[k].st));
const verLbl=MK.verLbl=sel=>{ const reg=sel==='s1'?S.me.reg:(S.sellers.find(s=>s.id===sel)||{}).reg; if(regOk(reg)){ const man=REG.some(([k])=>reg[k].st==='manual'); return (man?t('Documents reviewed by MENAFoods · ','راجعت منافودز المستندات · '):t('Registry-checked seller · ','بائع متحقق من السجلات · '))+dOnly(Math.max(...REG.map(([k])=>reg[k].ts))); } return t('Documents submitted · registry check pending','المستندات مقدّمة · التحقق من السجلات قيد الانتظار'); };
const REGST={ok:['ok',['Matched','مطابق']],manual:['ok',['Reviewed manually','رُوجع يدويًا']],fail:['bad',['No match','غير مطابق']],unavail:['warn',['Service unavailable','الخدمة غير متاحة']]};
const regRows=(reg,admin,sid)=>rows(REG.map(([k,l,src])=>{ const r=reg&&reg[k]; const s=r?REGST[r.st]:['mut',['Not checked','لم يُفحص']]; return {ic:r&&['ok','manual'].includes(r.st)?'check':'shield',tone:s[0]==='ok'?'ok':s[0]==='mut'?'mut':s[0],t:tt(l)+' · '+src,s:r?t('Checked ','فُحص ')+dt(r.ts):t('Checked when you save','يُفحص عند الحفظ'),pill:[s[0],tt(s[1])],end:admin&&r&&!['ok','manual'].includes(r.st)?btn(t('Confirm from documents','تأكيد من المستندات'),{act:'regman',arg:sid+':'+k,sm:true,k:'sec',lbl:t('Confirm from documents: ','تأكيد من المستندات: ')+tt(l)}):''}; }));
ACT.regman=a=>{ const [sid,k]=a.split(':'); const reg=sid==='s1'?S.me.reg:(S.sellers.find(s=>s.id===sid)||{}).reg; if(!reg) return; reg[k]={st:'manual',ts:now(),by:'admin'}; notify('seller','shield',['MENAFoods reviewed your documents','راجعت منافودز مستنداتك'],'s.verify'); save(); rr(); toast(t('Marked as reviewed from documents','عُلّم كمراجع من المستندات')); };

/* ---- privacy (PDPL) ---- */
const pdplNote=MK.pdplNote=purpose=>`<div class="pad"><div class="priv" role="note">${I('lock',20)}<div><b>${t('How we use this information','كيف نستخدم هذه المعلومات')}</b><p>${purpose} ${t('Stored in Saudi Arabia and kept while you sell with us, then for the period the law requires.','تُحفظ في المملكة طوال مدة بيعك معنا ثم للمدة التي يلزمها النظام.')} <button type="button" class="lnk in" data-act="pdpl">${t('Privacy notice & your rights','إشعار الخصوصية وحقوقك')}</button></p></div></div></div>`;
ACT.pdpl=()=>sheet(t('Seller privacy notice (sample)','إشعار خصوصية البائع (تجريبي)'),`<dl class="kv">${[[t('Who we are','من نحن'),t('MENAFoods, marketplace operator, Riyadh','منافودز، مشغّل السوق، الرياض')],[t('What we collect','ما نجمعه'),t('Business, signatory, bank and contact details, documents','بيانات المنشأة والمفوّض والبنك والتواصل والمستندات')],[t('Why','لماذا'),t('To verify sellers, pay you, issue tax invoices and meet legal duties','للتحقق من البائعين ودفع مستحقاتك وإصدار الفواتير الضريبية والوفاء بالالتزامات النظامية')],[t('Where','أين'),t('Stored in Saudi Arabia','تُحفظ في المملكة')],[t('How long','المدة'),t('While you sell with us, then as the law requires','طوال بيعك معنا ثم حسب النظام')],[t('Your rights','حقوقك'),t('Access, correct, delete or withdraw consent: privacy@menafoods.example','الاطلاع أو التصحيح أو الحذف أو سحب الموافقة: privacy@menafoods.example')]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>${btn(t('Close','إغلاق'),{act:'shclose',full:true})}`);

/* ---- step-up OTP ---- */
let stepCb=null;
const stepUp=MK.stepUp=(title,why,cb)=>{ stepCb=cb; const two=S.me.sec&&S.me.sec.m==='app'; sheet(title,`<p class="why">${why}</p><p class="why">${two?t('Enter the 6-digit code from your authenticator app.','أدخل الرمز المكون من 6 أرقام من تطبيق المصادقة.'):t('We sent a 6-digit code by SMS to the owner’s mobile ending ','أرسلنا رمزًا من 6 أرقام برسالة إلى جوال المالك المنتهي بـ ')+LTR('0000')+'.'}</p>${fld('otp',t('Verification code','رمز التحقق'),{req:true,ltr:true,mode:'numeric',max:6,ac:'one-time-code',hint:t('In this preview any 6 digits work.','في هذا العرض تعمل أي 6 أرقام.')})}${btns(btn(t('Verify','تحقق'),{act:'otpok'}),btn(t('Cancel','إلغاء'),{act:'shclose',k:'sec'}))}`); setTimeout(()=>{ const i=document.getElementById('f-otp'); i&&i.focus(); },50); };
ACT.otpok=()=>{ const sh=document.querySelector('.sh-wrap'); const i=sh.querySelector('#f-otp'); if(!/^\d{6}$/.test(i.value.trim())){ i.setAttribute('aria-invalid','true'); if(!sh.querySelector('#otp-e')) i.insertAdjacentHTML('afterend',`<p class="err" id="otp-e" role="alert">${t('Enter the 6-digit code','أدخل الرمز المكون من 6 أرقام')}</p>`); i.setAttribute('aria-describedby','otp-e'); i.focus(); return; } const cb=stepCb; stepCb=null; closeSheet(true); S.me.lastStep=now(); cb&&cb(); };

/* ---- return window + decisions ---- */
const retWin=MK.retWin=o=>o.items.some(i=>{ const p=prod(i.pid); return p&&PERISH.includes(p.storage); })?DAY:3*DAY;
const retSla=o=>o.ret.ts+(retWin(o)===DAY?24:48)*HOUR;
const tLeft=ts=>{ const d=ts-now(); if(d<=0) return t('overdue','متأخر'); const h=Math.floor(d/HOUR), m=Math.floor(d%HOUR/MIN); return h?t(`${h} h ${m} min left`,`متبقٍ ${h} س ${m} د`):t(`${m} min left`,`متبقٍ ${m} د`); };
MK.retDue=o=>`${dt(retSla(o),{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})} · ${pill(retSla(o)-now()<6*HOUR?'warn':'info',tLeft(retSla(o)))}`;
const RCODE=[['nodmg',['Photos don’t show the problem','الصور لا تُظهر المشكلة']],['late',['Reported after the return window','أُبلغ بعد مهلة الإرجاع']],['handling',['Stored or handled wrongly after delivery','خُزّن أو عومل بشكل خاطئ بعد التسليم']],['qty',['Quantity matches the delivery note','الكمية تطابق إذن التسليم']],['other',['Other','أخرى']]];
MK.retTimeline=o=>{ const r=o.ret; const E=[[r.ts,t('Buyer reported the problem','أبلغ المشتري عن المشكلة')+(r.photo?' · '+t('photo attached','مرفق صورة'):'')]].concat((r.log||[]).map(x=>[x.ts,tt(x.tx)])); if(r.esc) E.push([r.escTs||r.dec||r.ts,t('Buyer asked MENAFoods to review','طلب المشتري مراجعة منافودز')]); if(r.res) E.push([r.res,t('MENAFoods decided','قررت منافودز')]); E.sort((a,b)=>a[0]-b[0]);
 return sec(t('Evidence & history','الأدلة والسجل'),`<ol class="tl">${E.map(([ts,tx])=>`<li class="done"><span class="dotc">${I('check',14)}</span><b>${tx}</b><small>${dt(ts)}</small></li>`).join('')}</ol>`); };
MK.retDecision=o=>{ const r=o.ret; const d=UI.rdec||{k:'full'}; const max=retAmt(o);
 return sec(t('Your decision','قرارك'),`<div class="pad">${radio('rdk',[['full',t('Accept · full refund','قبول · استرداد كامل'),M(max)+' '+t('+ VAT','+ الضريبة')],['partial',t('Accept · partial refund','قبول · استرداد جزئي'),t('Refund part of the amount','استرداد جزء من المبلغ')],['replace',t('Send a replacement','إرسال بديل'),t('No refund — you deliver new stock','بلا استرداد — توصل مخزونًا جديدًا')],['decline',t('Decline with a reason','رفض مع ذكر السبب'),t('Evidence required','الدليل مطلوب')]],d.k,t('Decision','القرار'),{cards:true,act:'rdk',showLeg:false})}
 ${d.k==='partial'?fld('ramt',t('Refund amount (excl. VAT)','مبلغ الاسترداد (قبل الضريبة)'),{req:true,type:'number',min:1,step:'0.01',mode:'decimal',ltr:true,pre:'&#x20C1;',val:d.amt||'',hint:t('Up to ','حتى ')+fmt(max)}):''}
 ${d.k==='decline'?fld('rcode',t('Reason code','رمز السبب'),{req:true,opts:[['',t('Choose','اختر')]].concat(RCODE.map(([k,l])=>[k,tt(l)])),val:d.code||''})+`<p class="lbl">${t('Your evidence','دليلك')}</p>${d.ev?row({ic:'camera',tone:'ok',t:t('Delivery photo attached (simulated)','أُرفقت صورة التسليم (محاكاة)')}):btn(t('Attach delivery photo or note','أرفق صورة أو إذن التسليم'),{act:'rev',k:'sec',ic:'camera',sm:true})}${UI.err.rev?`<p class="err" role="alert">${UI.err.rev}</p>`:''}`:''}
 ${fld('rnote2',t('Note to the buyer','ملاحظة للمشتري'),{ta:true,max:300,val:d.note||'',req:d.k==='decline'})}
 <p class="why">${t('Refunds include VAT and are deducted from your next payout; commission on them is reversed. If the buyer disagrees, MENAFoods reviews the evidence.','الاسترداد يشمل الضريبة ويُخصم من دفعتك القادمة وتُعكس عمولته. إن لم يوافق المشتري تراجع منافودز الأدلة.')}</p>
 ${btn(t('Send decision','أرسل القرار'),{act:'rdec',arg:o.id,full:true})}</div>`); };
const rdKeep=()=>{ const f=form(document.getElementById('main')); UI.rdec=Object.assign(UI.rdec||{},{k:f.rdk||'full',amt:f.ramt,code:f.rcode,note:f.rnote2}); return UI.rdec; };
ACT.rdk=v=>{ rdKeep().k=v; clearErr(); rr(); const el=document.querySelector(`input[name=rdk][value="${v}"]`); el&&el.focus(); };
ACT.rev=()=>{ rdKeep().ev=1; delete UI.err.rev; rr(); toast(t('Evidence attached (simulated)','أُرفق الدليل (محاكاة)')); };
ACT.rdec=id=>{ const d=rdKeep(); const o=ordFor(id); const r=o.ret; const max=retAmt(o); const a=Number(d.amt);
 const R=[]; if(d.k==='partial') R.push(['ramt',a>0&&a<max,t('Enter an amount above 0 and below ','أدخل مبلغًا أكبر من 0 وأقل من ')+fmt(max)]); if(d.k==='decline'){ R.push(['rcode',!!d.code,t('Choose a reason code','اختر رمز السبب')]); R.push(['rev',!!d.ev,t('Attach your evidence','أرفق دليلك')]); R.push(['rnote2',(d.note||'').length>=5,t('Write a short note','اكتب ملاحظة موجزة')]); }
 if(R.length&&!check(R)) return rr(); clearErr();
 const lg=(en,ar)=>{ r.log=r.log||[]; r.log.push({ts:now(),tx:[en,ar]}); };
 if(d.k==='full'){ r.st='accepted'; r.sellerNote=d.note||['Refund approved','تمت الموافقة على الاسترداد']; lg('Seller approved a full refund','وافق البائع على استرداد كامل'); }
 if(d.k==='partial'){ r.st='partial'; r.amt=r2(a); r.sellerNote=['Partial refund ','استرداد جزئي '].map(x=>(d.note?d.note+' · ':'')+x+fmt(a)); lg('Seller approved a partial refund of '+fmt(a),'وافق البائع على استرداد جزئي '+fmt(a)); }
 if(d.k==='replace'){ r.st='replaced'; r.sellerNote=d.note||['Replacement on the way','البديل في الطريق']; lg('Seller is sending a replacement','يرسل البائع بديلًا'); }
 if(d.k==='decline'){ r.st='declined'; r.code=d.code; r.ev=1; r.sellerNote=RCODE.find(x=>x[0]===d.code)[1].map(x=>x+' — '+d.note); lg('Seller declined with evidence','رفض البائع مع دليل'); }
 r.dec=now(); UI.rdec=null; notify('buyer','ret',[`Seller responded to your return on #${o.id}`,`ردّ البائع على طلب الإرجاع ‎#${o.id}`],'b.order?id='+o.id); save(); rr(); toast(t('Decision sent · buyer notified','أُرسل القرار · أُبلغ المشتري')); };
MK.disDecision=o=>{ const r=o.ret; const max=retAmt(o); const due=(r.escTs||r.dec||r.ts)+48*HOUR;
 return sec(t('Decision','القرار'),`<div class="pad"><p class="why">${t('Decide by ','قرّر قبل ')}${dt(due)} · ${pill(due-now()<6*HOUR?'warn':'info',tLeft(due))}</p>${radio('ddk',[['b',t('Full refund','استرداد كامل')],['p',t('Partial refund','استرداد جزئي')],['r',t('Replacement','استبدال')],['s',t('No refund (seller’s favour)','بلا استرداد (لصالح البائع)')]],'b',t('Outcome','النتيجة'),{showLeg:true})}${fld('damt',t('Partial amount (excl. VAT)','المبلغ الجزئي (قبل الضريبة)'),{type:'number',min:1,step:'0.01',ltr:true,mode:'decimal',pre:'&#x20C1;',hint:t('Only for a partial refund · up to ','للاسترداد الجزئي فقط · حتى ')+fmt(max)})}${fld('dcode',t('Reason code','رمز السبب'),{req:true,opts:[['',t('Choose','اختر')],['evid_b',t('Buyer’s evidence is clear','دليل المشتري واضح')],['evid_s',t('Seller’s evidence is clear','دليل البائع واضح')],['shared',t('Shared responsibility','مسؤولية مشتركة')],['courier',t('Courier / cold-chain fault','خطأ المندوب / سلسلة التبريد')]]})}${fld('dnote',t('Decision note (both sides see this)','ملاحظة القرار (يراها الطرفان)'),{ta:true,req:true,max:300})}${btn(t('Send decision','أرسل القرار'),{act:'dres2',arg:o.id})}</div>`); };
ACT.dres2=id=>{ const f=form(document.getElementById('main')); const o=ordFor(id); const max=retAmt(o); const a=Number(f.damt);
 if(!check([['dcode',!!f.dcode,t('Choose a reason code','اختر رمز السبب')],['dnote',f.dnote.length>=5,t('Write a short decision note','اكتب ملاحظة قرار موجزة')],['damt',f.ddk!=='p'||(a>0&&a<max),t('Enter a partial amount below the full amount','أدخل مبلغًا جزئيًا أقل من المبلغ الكامل')]])) return rr();
 const r=o.ret; r.st={b:'resolved_b',p:'resolved_p',r:'resolved_r',s:'resolved_s'}[f.ddk||'b']; if(f.ddk==='p') r.amt=r2(a); r.adminNote=f.dnote; r.res=now(); r.log=r.log||[]; r.log.push({ts:now(),tx:['MENAFoods decision recorded ('+f.dcode+')','سُجل قرار منافودز ('+f.dcode+')']});
 notify('seller','scale',[`Dispute on #${o.id} resolved`,`حُسم النزاع على ‎#${o.id}`],'s.return?id='+o.id); notify('buyer','scale',[`Dispute on #${o.id} resolved`,`حُسم النزاع على ‎#${o.id}`],'b.order?id='+o.id); save(); rr(); toast(t('Decision sent to both sides','أُرسل القرار للطرفين')); };
wrapA('bescok',(orig,id)=>{ orig(id); const o=ordFor(id); if(o&&o.ret&&o.ret.st==='dispute'&&!o.ret.escTs){ o.ret.escTs=now(); save(); } });

/* ---- ZATCA tax invoices, credit notes, commission invoices ---- */
MK.REF['s.inv']=['Swiggy · “Download invoice” on order; talabat · View receipt; Faire · View invoice; buyer app b.invoice layout (QR + key facts + lines + totals)','4f00d41c','screens',['bd832419','e6140af3']];
const qrSvg=(seed,lbl)=>{ let x=seed*9301+49297; const rnd=()=>(x=(x*9301+49297)%233280)/233280; const n=25; let r=''; const fin=(cx,cy)=>`<rect x="${cx}" y="${cy}" width="7" height="7" fill="currentColor"/><rect x="${cx+1}" y="${cy+1}" width="5" height="5" fill="#fff"/><rect x="${cx+2}" y="${cy+2}" width="3" height="3" fill="currentColor"/>`;
 for(let i=0;i<n;i++) for(let j=0;j<n;j++){ if((i<8&&j<8)||(i<8&&j>n-9)||(i>n-9&&j<8)) continue; if(rnd()>.5) r+=`<rect x="${j}" y="${i}" width="1" height="1" fill="currentColor"/>`; }
 return `<svg class="qr" viewBox="-1 -1 ${n+2} ${n+2}" role="img" aria-label="${esc(lbl)}"><rect x="-1" y="-1" width="${n+2}" height="${n+2}" fill="#fff"/>${r}${fin(0,0)}${fin(n-7,0)}${fin(0,n-7)}</svg>`; };
const SVAT=sel=>sel==='s1'?(S.me.biz.vat||'—'):'300000000000003';
const invView=(q,who)=>{ const k=q.get('k')||'inv', id=q.get('id'); let H={}, L=[], T;
 if(k==='comm'){ const x=S.payouts.find(p=>p.id===id); if(!x) return empty('doc',t('Invoice not found','الفاتورة غير موجودة'),''); H={no:'MF-COMM-'+x.id,type:t('Tax invoice · commission','فاتورة ضريبية · عمولة'),from:t('MENAFoods Marketplace (sample)','سوق منافودز (تجريبي)'),fvat:'300000000000003',to:sellerName(x.sel||'s1'),tvat:SVAT(x.sel||'s1'),ts:x.ts}; L=[[t('Marketplace commission','عمولة السوق')+' · '+t('orders in payout #','طلبات الدفعة #')+x.id,1,x.comm]]; T={sub:x.comm,vat:x.cvat,tot:r2(x.comm+x.cvat)}; }
 else { const o=ordFor(id); if(!o) return empty('doc',t('Invoice not found','الفاتورة غير موجودة'),''); const cn=k==='cn'; if(cn&&!o.ret) return empty('doc',t('No credit note','لا إشعار دائن'),'');
  H={no:(cn?'CN-':'SINV-')+o.id,type:cn?t('Credit note','إشعار دائن'):t('Tax invoice','فاتورة ضريبية'),from:sellerName(o.sel),fvat:SVAT(o.sel),to:tt([o.buyer.en,o.buyer.ar]),tvat:'310000000000003',ts:cn?(o.ret.dec||o.ret.ts):((o.tl||{}).accepted||o.ts),ref:cn?'SINV-'+o.id:null};
  if(cn){ const a=retAmt(o); L=[[t('Refund · ','استرداد · ')+retReason(o.ret.reason),1,-a]]; T={sub:-a,vat:-r2(a*.15),tot:-r2(a*1.15)}; } else { L=o.items.map(i=>[tt([i.en,i.ar]),i.q,r2(i.unit*i.q)]); const X=ordTot(o); T={sub:X.sub,vat:X.vat,tot:X.tot}; } }
 const seed=[...H.no].reduce((a,c)=>a+c.charCodeAt(0),0);
 let h=sec('',`<div class="card pad inv-h"><div class="inv-qr">${qrSvg(seed,t('ZATCA QR code (sample)','رمز زاتكا (تجريبي)'))}</div><div class="rb">${kv([[t('Type','النوع'),H.type],[t('Number','الرقم'),LTR(H.no)],[t('Issue date','تاريخ الإصدار'),dtp(H.ts)],H.ref?[t('Corrects invoice','يصحح الفاتورة'),LTR(H.ref)]:null,[t('ZATCA status','حالة زاتكا'),pill('ok',t('Cleared (sample)','معتمدة (تجريبي)'))]])}</div></div>`,{raw:true});
 h+=sec(t('Seller','البائع'),kv([[t('Name','الاسم'),esc(H.from)],[t('VAT number','الرقم الضريبي'),LTR(H.fvat)]]))+sec(t('Customer','العميل'),kv([[t('Name','الاسم'),esc(H.to)],[t('VAT number','الرقم الضريبي'),LTR(H.tvat)]]));
 h+=sec(t('Lines','البنود'),L.map(([d,qn,a])=>row({ic:'doc',tone:'mut',t:esc(d),s:N(qn)+' ×',end:`<b>${M(a)}</b>`})).join('')+kv([[t('Total excl. VAT','الإجمالي قبل الضريبة'),M(T.sub)],[t('VAT 15%','الضريبة 15%'),M(T.vat)],[t('Total incl. VAT','الإجمالي شامل الضريبة'),M(T.tot),'tot']]));
 h+=`<div class="pad">${note(k==='comm'?t('Monthly commission invoice issued by MENAFoods with 15% VAT. Sample numbers.','فاتورة عمولة شهرية تصدرها منافودز مع ضريبة 15%. أرقام تجريبية.'):t('Issued in the seller’s name through MENAFoods (self-billing) and reported to ZATCA Fatoora. Sample numbers.','تصدر باسم البائع عبر منافودز (فوترة ذاتية) وتُبلّغ لمنصة فاتورة. أرقام تجريبية.'))}</div>`;
 return {b:h,dock:btn(t('Download PDF','نزّل PDF'),{act:'invpdf',arg:H.no,full:true,ic:'dl'})}; };
ACT.invpdf=no=>toast(t('PDF ready (simulated): ','ملف PDF جاهز (محاكاة): ')+no);
def('s.inv',{t:q=>q.get('k')==='cn'?t('Credit note','إشعار دائن'):t('Tax invoice','فاتورة ضريبية'),back:q=>q.get('k')==='comm'?'s.payout?id='+q.get('id'):q.get('k')==='cn'?'s.return?id='+q.get('id'):'s.order?id='+q.get('id'),tab:'s.orders',render:q=>invView(q,'s')});
