def('b.inv',{t:q=>q.get('k')==='cn'?t('Credit note','إشعار دائن'):t('Tax invoice','فاتورة ضريبية'),back:q=>'b.order?id='+q.get('id'),tab:'b.orders',render:q=>invView(q,'b')});
const invRows=(o,p)=>{ const R=[]; if(!['new','rejected'].includes(o.st)) R.push({ic:'doc',tone:'brand',t:t('Tax invoice','فاتورة ضريبية')+' '+LTR('SINV-'+o.id),s:t('ZATCA QR · PDF','رمز زاتكا · PDF'),go:p+'.inv?k=inv&id='+o.id}); if(o.ret&&['accepted','partial','resolved_b','resolved_p'].includes(o.ret.st)) R.push({ic:'doc',tone:'brand',t:t('Credit note','إشعار دائن')+' '+LTR('CN-'+o.id),s:t('For the refund','للاسترداد'),go:p+'.inv?k=cn&id='+o.id}); return R.length?sec(t('Invoices','الفواتير'),rows(R)):''; };
wrap('s.order',(o,q)=>{ const x=ordFor(q.get('id')); if(x) o.b+=invRows(x,'s'); });
wrap('b.order',(o,q)=>{ const x=ordFor(q.get('id')); if(x) o.b+=invRows(x,'b'); });
