/* ---- payouts: period, expected date, bank reference, commission invoice, hold ---- */
const holdAlert=()=>{ const h=S.me.bank.hold; return h&&h>now()?`<div class="pad">${alert_('warn',t('Payouts on hold until ','المدفوعات معلّقة حتى ')+dt(h),t('Your bank account changed. For your security we hold payouts for 48 hours after a change.','تغيّر حسابك البنكي. لحمايتك نعلّق المدفوعات 48 ساعة بعد التغيير.'),{role:'status'})}</div>`:''; };
const nextPay=()=>{ let d=now()+DAY; while(new Date(d).toLocaleDateString('en-US',{timeZone:'Asia/Riyadh',weekday:'short'})!=='Sun') d+=DAY; const h=S.me.bank.hold; return h&&h>d?h:d; };
wrap('s.payouts',o=>{ o.b=holdAlert()+o.b.replace('</p></div>',`</p>${kv([[t('Expected payout date','تاريخ الدفعة المتوقع'),dtp(nextPay())],[t('Period','الفترة'),dOnly(now()-7*DAY)+' – '+dOnly(now())]])}</div>`); });
wrap('s.payout',(o,q)=>{ const x=S.payouts.find(p=>p.id===q.get('id')); if(!x) return; const d=new Date(x.ts).toISOString().slice(0,10).replace(/-/g,'');
 o.b=before(o.b,`>${t('Statement','كشف الحساب')}</h2>`,sec(t('Payout details','تفاصيل الدفعة'),kv([[t('Period covered','الفترة المشمولة'),dOnly(x.ts-7*DAY)+' – '+dOnly(x.ts-DAY)],[t('Paid on','تاريخ الدفع'),dtp(x.ts)],[t('Bank reference','المرجع البنكي'),LTR('SARIE-'+d+'-'+x.id)],[t('Status','الحالة'),pill('ok',t('Paid','مدفوعة'))]]),{act:sample()}))+sec('',rows([{ic:'doc',tone:'brand',t:t('Commission tax invoice','الفاتورة الضريبية للعمولة')+' '+LTR('MF-COMM-'+x.id),s:t('Commission + 15% VAT · ZATCA QR','العمولة + 15% ضريبة · رمز زاتكا'),go:'s.inv?k=comm&id='+x.id}])); });

