const barH=()=>{ const a=document.querySelector('.app'); if(!a) return; const h=[...a.querySelectorAll(':scope>.tabbar,:scope>.dock')].filter(e=>getComputedStyle(e).display!=='none').reduce((s,e)=>s+e.offsetHeight,0); a.style.setProperty('--barH',h+'px'); document.documentElement.style.setProperty('--barH',h+'px'); };
