MK.boot=()=>{ load(); let root=document.getElementById('mk'); if(!root){ root=document.createElement('div'); root.id='mk'; document.body.prepend(root); } if(!document.getElementById('mk-toast')){ const tEl=document.createElement('div'); tEl.id='mk-toast'; tEl.className='toast'; tEl.setAttribute('role','status'); tEl.setAttribute('aria-live','polite'); document.body.appendChild(tEl); } render(true); };
